            pass

    # Fallback: iterate over the object itself (e.g. a dict or custom container)
    try:
        for idx, current_key in enumerate(self):
            if current_key == key:
                return idx
    except Exception as exc:
        raise TypeError(f"Failed to iterate over '{self}': {exc}") from exc

    # If the key was not found, raise an informative error
    raise ValueError(f"'{key}' is not present in {self}")

