        if isinstance(data, dict):
            keys_list = list(data.keys())
            values_list = list(data.values())
        else:
            # Expect iterable of (key, value) pairs
            items = list(data)
            keys_list = [k for k, _ in items]
            values_list = [v for _, v in items]
    except Exception as exc:
        raise TypeError(f"Unable to interpret underlying data: {exc}") from exc
