        provided in the items that are not in the record will be
        inserted with a value of :const:`None`; indexes provided
        that are out of bounds will trigger an :exc:`IndexError`.

        :param keys: indexes or keys of the items to include; if none
                      are provided, all values will be included
        :return: dictionary of values, keyed by field name
        :raises: :exc:`IndexError` if an out-of-bounds index is specified
        """
        # Determine the key list and data list from the record.
        # The implementation assumes the following attributes exist:
        #   - self._keys: list of field names in order
        #   - self._data: list of field values in the same order
        #   - optionally self._keymap: mapping name -> index for fast lookup
        try:
            keys_list = self._keys
            data_list = self._data
        except AttributeError:
            # If the record uses different attribute names, try common alternatives
            keys_list = getattr(self, 'keys', None)
            data_list = getattr(self, 'data', None)
            if keys_list is None or data_list is None:
                raise AttributeError("Record object does not expose _keys and _data attributes")
        # Build a quick lookup map if available.
        keymap = getattr(self, "_keymap", None)
        if keymap is None:
            # Build a map on demand
            keymap = {k: i for i, k in enumerate(keys_list)}
        n_items = len(keys_list)

        # If no keys requested, return all as dict
        if not keys:
            return dict(zip(keys_list, data_list))

        result = {}
        for k in keys:
            if isinstance(k, int):
                # Handle negative indices like typical list indexing
                if k < 0:
                    k = n_items + k
                if not (0 <= k < n_items):
                    raise IndexError(f"Index {k} out of bounds for record with {n_items} fields")
                key_name = keys_list[k]
                result[key_name] = data_list[k]
            else:
                # Assume key is a string (field name)
                if k in keymap:
                    idx = keymap[k]
                    result[k] = data_list[idx]
                else:
                    # Field not present; set to None
                    result[k] = None
        return result

def data(self, *keys):
    """Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key.
    Keys provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # The method assumes the record stores a list of field names in
    # self._keys and the corresponding values in self._values.  If the
    # attributes are missing a more descriptive AttributeError is
    # raised, otherwise the method may work with a simple dict stored
    # in self._data as a fallback.
    keys_attr = getattr(self, "_keys", None)
    vals_attr = getattr(self, "_values", None)

    if keys_attr is None and vals_attr is None:
        # Try a dict based record
        data_dict = getattr(self, "_data", None)
        if data_dict is None:
            raise AttributeError("Record must provide _keys/_values or _data attributes")
        # If a dictionary is available, just slice or filter it
        if not keys:
            return dict(data_dict)
        result = {}
        for k in keys:
            if isinstance(k, int):
                # treat int as a key string if present
                key = k if k in data_dict else str(k)
                result[key] = data_dict.get(key, None)
            else:
                result[k] = data_dict.get(k, None)
        return result

    if keys_attr is None or vals_attr is None:
        raise AttributeError("Record missing _keys or _values attributes")

    names = list(keys_attr)
    values = list(vals_attr)

    if len(names) != len(values):
        raise ValueError("Record _keys and _values lengths differ")

    name_to_index = {name: i for i, name in enumerate(names)}
    result = {}

    if not keys:
        for name, val in zip(names, values):
            result[name] = val
        return result

    for k in keys:
        if isinstance(k, int):
            if k < 0 or k >= len(values):
                raise IndexError(f"Index {k} out of bounds for record")
            name = names[k]
            result[name] = values[k]
        else:
            if k in name_to_index:
                idx = name_to_index[k]
                result[k] = values[idx]
            else:
                result[k] = None

    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
            hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Validate arguments
    if not isinstance(n, int):
        raise TypeError(f"n must be int, got {type(n).__name__}")
    if not isinstance(qid, int):
        raise TypeError(f"qid must be int, got {type(qid).__name__}")
    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise TypeError("dehydration_hooks must be a dict or None")
    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise TypeError("hydration_hooks must be a dict or None")

    # Prepare the message dictionary
    message = {"type": "DISCARD", "n": n, "qid": qid}

    # Apply dehydration hooks if provided
    if dehydration_hooks:
        for key, value in list(message.items()):
            hook = dehydration_hooks.get(type(value))
            if hook:
                try:
                    message[key] = hook(value)
                except Exception as exc:
                    raise RuntimeError(
                        f"Dehydration hook for {key} ({type(value).__name__}) "
                        f"raised an exception") from exc

    try:
        # Encode the message; fall back to raw dict if encoder not available
        if hasattr(self, "_pack_stream"):
            encoded = self._pack_stream(
                message,
                dehydration_hooks=dehydration_hooks,
                hydration_hooks=hydration_hooks
            )
        else:
            encoded = message
    except Exception as exc:
        raise RuntimeError("Failed to encode DISCARD message") from exc

    # Append to the output queue
    if not hasattr(self, "_output_queue"):
        raise AttributeError("Instance missing an '_output_queue' attribute")
    self._output_queue.append(encoded)

    # Return a Response object if the helper exists, otherwise None
    if hasattr(self, "_build_response"):
        try:
            return self._build_response(encoded, **handlers)
        except Exception as exc:
            raise RuntimeError("Failed to build response object") from exc
    return None

