            if not callable(fn):
                raise TypeError(f"Dehydration hook for {key} is not callable")
    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise TypeError(f"'hydration_hooks' must be a dict, got {type(hydration_hooks).__name__}")
        for key, fn in hydration_hooks.items():
            if not callable(fn):
                raise TypeError(f"Hydration hook for {key} is not callable")

