    try:
        # The protocol typically has a method to enqueue messages.
        if hasattr(self, "_queue_message"):
            # Some protocols use constants for message types; fallback to string.
            message_type = getattr(self, "MessageTypes", None)
            if message_type is not None and hasattr(message_type, "DISCARD"):
                self._queue_message(message_type.DISCARD, payload)
            else:
                self._queue_message("DISCARD", payload)
