def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    Parameters
    ----------
    name : str
        The name of the new subclass.
    fields : Iterable[Tuple[str, type] | Tuple[str, type, Any]]
        Each element is either a `(field_name, field_type)` or
        ``(field_name, field_type, default_value)`` tuple describing an
        attribute to add to the subclass.
    srid_map : Mapping
        A mapping that will be stored on the class as ``SRID_MAP``.
    Returns
    -------
    type
        The new subclass of :class:`shapely.geometry.Point`.
    """
    # Basic input validation ---------------------------------------------------
    if not isinstance(name, str):
        raise TypeError("name must be a string")

    if not hasattr(fields, "__iter__"):
        raise TypeError("fields must be an iterable of tuples")

    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")

    # Import the base Point class lazily --------------------------------------
    try:
        from shapely.geometry import Point
    except Exception as exc:
        raise ImportError("Could not import shapely.geometry.Point") from exc

    # Build the class dictionary -----------------------------------------------
    class_dict: dict[str, Any] = {}
    annotations: dict[str, type] = {}

    for entry in fields:
        if not isinstance(entry, (list, tuple)):
            raise TypeError("Each field definition must be a tuple")
        if len(entry) == 2:
            fname, ftype = entry
            default_val = None
        elif len(entry) == 3:
            fname, ftype, default_val = entry
        else:
            raise ValueError("Field tuple must have 2 or 3 elements")

        if not isinstance(fname, str):
            raise TypeError("Field name must be a string")

        # Store the attribute with its default value;
        # if default_val is supplied, use it, otherwise keep None.
        class_dict[fname] = default_val
        annotations[fname] = ftype

    if annotations:
        class_dict["__annotations__"] = annotations

    class_dict["SRID_MAP"] = srid_map

    # Create and return the subclass ------------------------------------------
    return type(name, (Point,), class_dict)

