def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can only be configured
    via R options once R has started. These are set here.
    """
    if not isinstance(code, str):
        raise TypeError("The `code` argument must be a string.")
    # If the code is empty, nothing to do.
    if code.strip() == "":
        return code

    try:
        # Common R options that are typically set programmatically.
        # Adjust as necessary for your R environment.
        options = {
            "stringsAsFactors": False,
            "scipen": 999,
            "digits": 10,
            "warn": 2,  # Turn warnings into errors
            "max.print": 99999,
        }

        option_lines = []
        for name, value in options.items():
            if isinstance(value, str):
                val_repr = f'"{value}"'
            else:
                val_repr = str(value)
            option_lines.append(f'options({name}={val_repr})')
        # Join the option lines and prepend them to the provided R code.
        options_block = "\n".join(option_lines) + "\n\n"
        return options_block + code
    except Exception as exc:
        raise RuntimeError(f"Failed to set inline R options: {exc}") from exc

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    from concurrent.futures import ThreadPoolExecutor, as_completed

    # Helper to form groups of varargs that fit within the max command line length.
    def build_groups() -> list[list[str]]:
        groups: list[list[str]] = []
        current: list[str] = []
        current_length = sum(len(part) for part in cmd) + len(cmd)  # spaces between cmd parts
        for arg in varargs:
            # Length with preceding space
            arg_len = len(arg) + 1
            if current_length + arg_len > _max_length and current:
                groups.append(current)
                current = [arg]
                current_length = sum(len(part) for part in cmd) + len(cmd) + arg_len
            else:
                current.append(arg)
                current_length += arg_len
        if current:
            groups.append(current)
        return groups

    def run_group(group_args: list[str]) -> tuple[int, bytes]:
        full_cmd = list(cmd) + group_args
        try:
            # If color is True and pty is supported, we could allocate a pty here.
            # For simplicity, we ignore pty allocation.
            result = subprocess.run(
                full_cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                **kwargs,
            )
            return result.returncode, result.stdout
        except Exception as exc:
            # Wrap exception into a return code 1 and empty output
            return 1, str(exc).encode()

    groups = build_groups()
    if not groups:
        # No arguments to pass; just run the command.
        groups = [[]]

    overall_retcode = 0
    combined_output: bytearray = bytearray()

    if target_concurrency > 1:
        with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
            futures = {executor.submit(run_group, g): g for g in groups}
            for fut in as_completed(futures):
                rc, out = fut.result()
                combined_output.extend(out)
                if rc != 0 and overall_retcode == 0:
                    overall_retcode = rc
    else:
        for g in groups:
            rc, out = run_group(g)
            combined_output.extend(out)
            if rc != 0 and overall_retcode == 0:
                overall_retcode = rc

    return overall_retcode, bytes(combined_output)

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    try:
        # Verify all elements are strings
        for i, elem in enumerate(seq):
            if not isinstance(elem, str):
                raise TypeError(f"Element at index {i} is not a string: {elem!r}")
        # Convert to list to allow modification
        items = list(seq)
        n = len(items)
        # Deterministic shuffle using a simple linear congruential style index computation
        for i in range(1, n):
            # Use the first character ordinal if available, otherwise 0
            key = ord(items[i][0]) if items[i] else 0
            j = (key + i) % (i + 1)
            items[i], items[j] = items[j], items[i]
        return items
    except Exception as e:
        # Preserve original exception type and message for visibility
        raise e from None

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    parts = s.strip().split('.')
    nums: list[int] = []
    for part in parts:
        if not part:
            continue
        # Take anything before a hyphen (e.g., "3-alpha" -> "3")
        stripped = part.split('-', 1)[0]
        try:
            nums.append(int(stripped))
        except ValueError:
            # Ignore parts that cannot be converted to integers
            continue
    if not nums:
        # Default to zero if nothing matched
        return (0,)
    return tuple(nums)

