@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception into a readable string with a truncated stack trace.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum number of traceback frames to include (default 30)
        :type max_level: int
        :param max_path_level: Maximum depth of file path components to display (default 5)
        :type max_path_level: int
        :return str: Human‑readable exception description
        """
        try:
            if e is None or not isinstance(e, BaseException):
                raise TypeError("The 'e' argument must be an Exception instance")

            import os, traceback

            # Normalise limits
            if not isinstance(max_level, int) or max_level <= 0:
                max_level = None  # show all
            if not isinstance(max_path_level, int) or max_path_level <= 0:
                max_path_level = 1

            tb = e.__traceback__
            # If no traceback, try the cause or context fallback
            if tb is None:
                tb = getattr(e, "__cause__", None) or getattr(e, "__context__", None)

            # Extract frames; if still None, we'll just rely on message
            frames = []
            if tb is not None:
                extracted = traceback.extract_tb(tb)
                frames = extracted[:max_level] if max_level is not None else extracted

            def _shrink_path(path):
                """Return a shortened version of a path, keeping at most max_path_level components."""
                parts = path.split(os.sep)
                if len(parts) <= max_path_level:
                    return path
                # keep first, last max_path_level-1
                return os.sep.join(
                    parts[:1] + ["..."] + parts[-(max_path_level-1):]
                )

            lines = [f"{type(e).__name__}: {e}"]

            if frames:
                lines.append("Traceback (most recent call last):")
                for frm in frames:
                    file_path = _shrink_path(frm.filename) if frm.filename else "<unknown>"
                    line_no = frm.lineno
                    func_name = frm.name
                    lines.append(f'  File "{file_path}", line {line_no}, in {func_name}')
                    # Include the line of code if available
                    if frm.line:
                        # strip trailing newlines and leading spaces for pretty printing
                        code = frm.line.strip()
                        if code:
                            lines.append(f'    {code}')

            return "\n".join(lines)

        except Exception:
            # Fallback: return plain string representation of the exception
            return str(e) or repr(e)

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    import traceback, os
    # If e is not an exception instance, just return its string representation
    if not isinstance(e, BaseException):
        return str(e)

    def _shorten_path(path):
        parts = path.split(os.sep)
        if len(parts) <= max_path_level:
            return path
        return os.sep.join(parts[-max_path_level:])

    def _format_single_exc(exc):
        lines = [f"{exc.__class__.__name__}: {exc}"]
        tb = exc.__traceback__
        if tb is not None:
            extracted = traceback.extract_tb(tb, limit=max_level)
            for frame in extracted:
                filename = _shorten_path(frame.filename)
                lines.append(f'  File "{filename}", line {frame.lineno}, in {frame.name}')
                if frame.line:
                    stripped = frame.line.strip()
                    if stripped:
                        lines.append(f'    {stripped}')
        return "\n".join(lines)

    try:
        formatted = []
        current = e
        while current:
            formatted.append(_format_single_exc(current))
            if current.__cause__:
                current = current.__cause__
            elif current.__context__ and not current.__suppress_context__:
                current = current.__context__
            else:
                current = None
        return "\n\n".join(formatted)
    except Exception as fmt_err:
        return f"Error formatting exception: {fmt_err}"

@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        # Basic validation
        if not isinstance(e, BaseException):
            raise TypeError(f"Expected an Exception instance, got {type(e)!r}")

        # Ensure limits are positive integers
        try:
            max_level = int(max_level)
            max_path_level = int(max_path_level)
            if max_level < 1:
                max_level = 1
            if max_path_level < 1:
                max_path_level = 1
        except Exception:
            max_level, max_path_level = 30, 5

        # Prepare traceback information
        try:
            exc_tb = e.__traceback__
            if exc_tb is None:
                stack_frames = []
            else:
                # Use TracebackException to capture frames
                tb_exc = traceback.TracebackException.from_exception(e)
                stack_frames = tb_exc.stack
        except Exception:
            stack_frames = []

        # Build output lines
        lines = [f"{e.__class__.__name__}: {e}"]
        if stack_frames:
            lines.append("Traceback (most recent call last):")
            for frame in stack_frames[:max_level]:
                # Shorten file path
                path = frame.filename
                try:
                    parts = path.split(os.sep)
                    if len(parts) > max_path_level:
                        path = os.sep.join(parts[-max_path_level:])
                except Exception:
                    pass  # fallback to original path
                lines.append(f'  File "{path}", line {frame.lineno}, in {frame.name}')
                if frame.line:
                    code_line = frame.line.strip()
                    if code_line:
                        lines.append(f'    {code_line}')
        return "\n".join(lines)

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string, limiting the depth of the
    traceback and the file path components shown.

    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum number of stack frames to include (default 30).
    :type max_level: int
    :param max_path_level: Maximum number of components of a file path to
                           include from the right (default 5).
    :type max_path_level: int
    :return: A readable string representation of the exception.
    :rtype: str
    """
    try:
        import traceback, os
    except Exception:
        # If import fails, fall back to a very minimal representation
        return f"{type(e).__name__}: {e}"

    # Build base exception line
    exc_line = f"{type(e).__name__}: {e}"
    # If there is no traceback, simply return the exc line
    if not hasattr(e, "__traceback__") or e.__traceback__ is None:
        return exc_line

    # Retrieve the traceback object via TracebackException for uniform
    # formatting, but we will manually format to control path depth.
    try:
        trb = traceback.TracebackException.from_exception(e)
        stack_frames = list(trb.stack)[:max_level]
    except Exception:
        # If something goes wrong, just include the standard traceback
        return ''.join(traceback.format_exception_only(type(e), e)).strip()

    # Helper to shorten file path
    def shorten_path(path):
        if not path:
            return path
        parts = path.split(os.sep)
        if len(parts) > max_path_level:
            return os.sep.join(parts[-max_path_level:])
        return path

    formatted_lines = ["Traceback (most recent call last):"]
    for frame in stack_frames:
        # FrameSummary has filename, lineno, name, line
        file_path = shorten_path(frame.filename)
        formatted_lines.append(
            f'  File "{file_path}", line {frame.lineno}, in {frame.name}'
        )
        line_text = frame.line.strip() if frame.line else ""
        if line_text:
            formatted_lines.append(f'    {line_text}')

    formatted_lines.append(exc_line)

    return '\n'.join(formatted_lines)

