@classmethod
    def _reset_logging(cls):
        """
        Reset the global logging configuration to a clean default state.
        This removes all handlers from the root logger, sets its level
        to INFO, and reinitialises the basic configuration with a
        simple format.  The method is tolerant to the logging module
        not being available; in that case it simply returns without
        raising an exception.  No value is returned.
        """
        try:
            root = logging.getLogger()
        except NameError:
            # logging module not available, nothing to reset
            return

        # Remove all handlers from the root logger
        for handler in root.handlers[:]:
            try:
                root.removeHandler(handler)
            except Exception:
                # Ignore any errors while removing handlers
                pass

        # Reset the root logger's level
        root.setLevel(logging.INFO)

        # Add a basic configuration if there are no handlers left
        if not root.handlers:
            try:
                logging.basicConfig(
                    level=logging.INFO,
                    format="%(levelname)s:%(name)s:%(message)s"
                )
            except Exception:
                # If basicConfig fails for any reason, ignore it
                pass

        return

