def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Collect all unique elements and their first occurrence index
    first_index = {}
    index = 0
    for ording in orderings:
        for item in ording:
            if item not in first_index:
                first_index[item] = index
                index += 1
    # Build adjacency list and indegree counts
    adj = {item: set() for item in first_index}
    indeg = {item: 0 for item in first_index}
    for ording in orderings:
        # Remove consecutive duplicates to avoid self loops
        prev = None
        for item in ording:
            if item == prev:
                continue
            if prev is not None:
                if item not in adj[prev]:
                    adj[prev].add(item)
                    indeg[item] += 1
            prev = item
    # Kahn's algorithm with priority by first appearance
    import heapq
    heap = []
    for item, deg in indeg.items():
        if deg == 0:
            heapq.heappush(heap, (first_index[item], item))
    result = []
    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)
        for nb in adj[node]:
            indeg[nb] -= 1
            if indeg[nb] == 0:
                heapq.heappush(heap, (first_index[nb], nb))
    if len(result) != len(first_index):
        raise ValueError("Cannot merge orderings due to cycle or invalid constraints")
    return result

