def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    else:
        if not isinstance(output, list):
            raise TypeError("output must be a list or None")

    def is_impl_spec(item):
        # Heuristic: a tuple/list of length 2 where both elements are
        # either strings or types represents an implements specification
        if isinstance(item, (tuple, list)) and len(item) == 2:
            a, b = item
            return isinstance(a, (str, type)) and isinstance(b, (str, type))
        return False

    for arg in sequence:
        # Skip if arg is None
        if arg is None:
            continue
        # Recursively expand any iterable that is not an implement spec
        if isinstance(arg, (tuple, list)):
            if is_impl_spec(arg):
                output.append(arg)
            else:
                try:
                    _normalizeargs(arg, output)
                except TypeError:
                    # Treat as indivisible element if it cannot be iterated
                    output.append(arg)
        else:
            output.append(arg)

    return tuple(output)

def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    # Import necessary modules lazily to avoid global imports
    try:
        import os
        import sys
    except Exception:
        # If import fails, we shouldn't attempt C optimizations
        return False

    # Respect user request for pure Python mode
    try:
        pure_python_flag = os.getenv("PURE_PYTHON")
    except Exception:
        pure_python_flag = None
    if pure_python_flag:
        return False

    # Avoid using C extensions on PyPy, where the C implementation may not be supported
    try:
        # sys.implementation is available on CPython 3.x and PyPy 3.x
        implementation_name = getattr(sys, "implementation", None)
        if implementation_name and getattr(implementation_name, "name", "").lower() == "pypy":
            return False
    except Exception:
        # If for some reason we can't determine the implementation, default to attempting C
        pass

    return True

