def _update_context(self, context):
    """
    Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    try:
        # Determine the ordered list of field names for the graph
        if hasattr(self, "columns"):
            try:
                field_names = list(self.columns)
            except Exception:
                field_names = []
        elif hasattr(self, "keys"):
            try:
                field_names = list(self.keys())
            except Exception:
                field_names = []
        elif hasattr(self, "_keys"):
            try:
                field_names = list(self._keys)
            except Exception:
                field_names = []
        else:
            field_names = []

        # Map field names to their indices
        field_index_map = {name: idx for idx, name in enumerate(field_names)}

        # Retrieve or initialise the error sub‑context
        if hasattr(context, "error"):
            err_ctx = context.error
            if not isinstance(err_ctx, dict):
                err_ctx = {}
        elif isinstance(context, dict) and "error" in context:
            err_ctx = context["error"]
            if not isinstance(err_ctx, dict):
                err_ctx = {}
        else:
            err_ctx = {}
            # If context is a dict, store it back
            if isinstance(context, dict):
                context["error"] = err_ctx

        # Coordinates mapping for the first three dimensions
        coord_names = ["x", "y", "z"]

        # Process each field and add corresponding error entries
        for idx, fname in enumerate(field_names):
            # Look for fields that look like 'error_*_<side>'
            if fname.startswith("error_") and (fname.endswith("_low") or fname.endswith("_high")):
                side = fname.rsplit("_", 1)[1]  # "low" or "high"
                # Determine the coordinate based on the field index position
                if idx < len(coord_names):
                    coord = coord_names[idx]
                else:
                    # If more than three dimensions, skip or use a generic key
                    coord = f"dim{idx}"

                key = f"{coord}_{side}"
                err_ctx[key] = {"index": idx}

        # If context was a dict, update its 'error' entry
        if isinstance(context, dict):
            context["error"] = err_ctx
        else:
            context.error = err_ctx
    except Exception as exc:
        # Log or re‑raise as needed; here we raise a ValueError with context
        raise ValueError(f"Failed to update context: {exc}") from exc

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    try:
        import numpy as np
    except Exception as exc:
        raise ImportError("numpy is required for integral calculation") from exc

    # Convert inputs to NumPy arrays
    try:
        bins_arr = np.asarray(bins, dtype=float)
        edges_arr = np.asarray(edges, dtype=float)
    except Exception as exc:
        raise TypeError("bins and edges must be array-like") from exc

    # Validate dimensionality
    if bins_arr.ndim != 1 or edges_arr.ndim != 1:
        raise ValueError("bins and edges must be one‑dimensional")

    # Validate length relationship
    if len(edges_arr) != len(bins_arr) + 1:
        raise ValueError("Number of edges must be exactly one more than number of bins")

    # Compute widths and ensure they are non‑negative
    widths = edges_arr[1:] - edges_arr[:-1]
    if np.any(widths < 0):
        raise ValueError("Histogram edges must be in ascending order")

    # Compute integral
    return np.sum(bins_arr * widths)

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate inputs
    if not isinstance(bins, (list, tuple)):
        raise TypeError("bins must be a list or tuple")
    if not isinstance(edges, (list, tuple)):
        raise TypeError("edges must be a list or tuple")
    if len(edges) != len(bins) + 1:
        raise ValueError("Length of edges must be one more than length of bins")
    # Convert to floats and validate monotonic increasing edges
    try:
        edges_f = [float(e) for e in edges]
        bins_f = [float(b) for b in bins]
    except Exception as exc:
        raise ValueError(f"Bins and edges must be numeric: {exc}") from exc
    for i in range(len(edges_f) - 1):
        if edges_f[i] >= edges_f[i + 1]:
            raise ValueError("Edges must be strictly increasing")
    # Compute widths and integral
    total = 0.0
    for b, e0, e1 in zip(bins_f, edges_f[:-1], edges_f[1:]):
        width = e1 - e0
        total += b * width
    return total

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate input iterables
    try:
        bins_list = list(bins)
    except TypeError:
        raise TypeError("bins must be an iterable (e.g., list or array).")

    try:
        edges_list = list(edges)
    except TypeError:
        raise TypeError("edges must be an iterable (e.g., list or array).")

    n_bins = len(bins_list)

    # If there are no bins, the integral is zero
    if n_bins == 0:
        return 0.0

    # The number of edges must be one more than the number of bins
    if len(edges_list) != n_bins + 1:
        raise ValueError(
            f"Number of edges ({len(edges_list)}) must be one more than number of bins ({n_bins})."
        )

    # Compute the widths of each bin
    widths = []
    for i in range(n_bins):
        try:
            width = float(edges_list[i + 1]) - float(edges_list[i])
        except Exception as exc:
            raise TypeError(
                "Edge values must be numeric and support subtraction."
            ) from exc
        widths.append(width)

    # Sum the product of bin values and widths
    total = 0.0
    for value, width in zip(bins_list, widths):
        try:
            total += float(value) * float(width)
        except Exception as exc:
            raise TypeError(
                "Bin values must be numeric (or convertible to float)."
            ) from exc

    return total

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert to list for flexible indexing
    try:
        bins_list = list(bins)
        edges_list = list(edges)
    except Exception as exc:
        raise TypeError("bins and edges must be iterable") from exc

    # Validate lengths
    if len(edges_list) != len(bins_list) + 1:
        raise ValueError("Edges length must be one more than bins length")

    # Handle empty histogram
    if not bins_list:
        return 0.0

    total = 0.0
    try:
        for i, bin_val in enumerate(bins_list):
            width = edges_list[i + 1] - edges_list[i]
            total += float(bin_val) * float(width)
    except Exception as exc:
        raise ValueError("Invalid numeric values in bins or edges") from exc

    return total

