def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure we have the necessary attributes
    if not hasattr(self, "edges") or not hasattr(self, "bins"):
        raise AttributeError("Histogram missing 'edges' or 'bins' attribute")
    edges = self.edges
    ndim = len(edges)

    # Validate coordinate
    try:
        coord = tuple(coord)
    except Exception:
        raise TypeError("coord must be a sequence of values")
    if len(coord) != ndim:
        raise ValueError(f"Coordinate dimension {len(coord)} does not match histogram dimension {ndim}")

    # Convert weight to float, allowing numeric types
    try:
        w = float(weight)
    except Exception:
        raise ValueError("weight must be a numeric value")

    # Determine bin indices for each dimension
    bin_indices = []
    for d, val in enumerate(coord):
        edge = edges[d]
        if not hasattr(edge, "__len__"):
            raise TypeError(f"edges[{d}] is not a sequence")
        # Find the bin index using binary search
        try:
            import numpy as np
            idx = np.searchsorted(edge, val, side="right") - 1
        except ImportError:
            # Fallback to manual search if numpy is unavailable
            idx = -1
            for i in range(len(edge) - 1):
                if edge[i] <= val < edge[i + 1]:
                    idx = i
                    break

        # Ignore coordinates outside the histogram bounds
        if idx < 0 or idx >= len(edge) - 1:
            return

        bin_indices.append(idx)

    # Increment histogram count
    try:
        import numpy as np
        if isinstance(self.bins, np.ndarray):
            self.bins[tuple(bin_indices)] += w
        elif isinstance(self.bins, dict):
            key = tuple(bin_indices)
            self.bins[key] = self.bins.get(key, 0.0) + w
        else:
            raise TypeError("Unsupported bins data type")
    except ImportError:
        # If numpy is not available, assume bins is a simple list of lists
        if isinstance(self.bins, list):
            sub = self.bins
            for idx in bin_indices[:-1]:
                sub = sub[idx]
            sub[bin_indices[-1]] += w
        else:
            raise TypeError("Unsupported bins data type without numpy")
    return None

def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Validate weight
        try:
            weight_val = float(weight)
        except Exception:
            raise TypeError(f"weight must be numeric, got {weight!r}")

        # Ensure coord is iterable and matches dimensionality
        if not hasattr(coord, "__iter__"):
            raise ValueError(f"coord must be an iterable, got {coord!r}")
        try:
            coord_list = list(coord)
        except Exception:
            raise ValueError(f"coord could not be converted to a list, got {coord!r}")

        if not hasattr(self, "edges"):
            raise AttributeError("Histogram object has no 'edges' attribute")
        dims = len(self.edges)
        if len(coord_list) != dims:
            raise ValueError(f"coord dimension {len(coord_list)} does not match histogram dimension {dims}")

        # Determine bin indices for each dimension
        indices = []
        for dim, (c, edges) in enumerate(zip(coord_list, self.edges)):
            # Validate edges
            if not hasattr(edges, "__iter__"):
                raise ValueError(f"edges[{dim}] is not iterable")
            edges_list = list(edges)
            if len(edges_list) < 2:
                # No bins defined for this dimension
                return  # Ignore: nothing to fill
            # Find bin: edges[i] <= c < edges[i+1]
            # Use numpy if available, otherwise fall back to linear search
            try:
                import numpy as np
                idx = np.searchsorted(edges_list, c, side="right") - 1
            except Exception:
                idx = -1
                for i in range(len(edges_list) - 1):
                    if edges_list[i] <= c < edges_list[i + 1]:
                        idx = i
                        break
            # Check outside bounds
            if idx < 0 or idx >= len(edges_list) - 1:
                return  # ignore coordinates outside histogram bounds
            indices.append(idx)

        # All dimensions within bounds, increment histogram bin
        try:
            self.hist[tuple(indices)] += weight_val
        except Exception as e:
            # Provide a clear error message indicating the failure point
            raise RuntimeError(f"Failed to increment histogram bin {tuple(indices)}: {e}") from e
        return None

