def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Recursively generate a default observer schema dictionary from a partial
    Kubernetes resource represented by ``manifest_dict``.

    All non-dict and non-list values are replaced by ``None`` unless the dictionary
    is the first level of the schema – in that case the values of identifying
