    Raises:
        TypeError: If ``manifest_dict`` is not a dictionary.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dictionary")

    def _process_item(item, level_first):
        if isinstance(item, dict):
            return generate_default_observer_schema_dict(item, first_level=False)
        if isinstance(item, list):
            return generate_default_observer_schema_list(item, first_level=False)
        # Primitive value
        return item if level_first else None

    try:
        result = {}
        for key, val in manifest_dict.items():
            result[key] = _process_item(val, first_level)
        return result
    except Exception as exc:
        raise RuntimeError(f"Failed to generate observer schema dict: {exc}") from exc

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generate a skeleton observer schema dict from a manifest dict.

    This function traverses ``manifest_dict`` and produces a new dictionary
    mirroring the structure, but replaces all scalar values (neither
    ``list`` nor ``dict``) with ``None``.  When ``first_level`` is ``True``,
    indicating that ``manifest_dict`` represents a whole Kubernetes
    resource, only the identifying fields are kept from the original
    manifest: ``apiVersion``, ``kind`` and the ``metadata`` sub‑keys
    ``name`` and ``namespace``.  All other top‑level keys are replaced
    with ``None`` and ``metadata`` children that are not ``name``/``namespace``
    become ``None`` as well.

    The function is robust to missing keys and non‑dict input by simply
    returning ``None`` for unsupported values.
    """
    def _process(value, first):
        if isinstance(value, dict):
            result = {}
            for k, v in value.items():
                if first and k in ("apiVersion", "kind"):
                    result[k] = v
                elif first and k == "metadata":
                    if isinstance(v, dict):
                        md = {}
                        for mk, mv in v.items():
                            if mk in ("name", "namespace"):
                                md[mk] = mv
                            else:
                                md[mk] = None
                        result[k] = md
                    else:
                        result[k] = None
                elif first:
                    # Any other top‑level key at first level becomes None
                    result[k] = None
                else:
                    # Recursive processing for deeper levels
                    result[k] = _process(v, False)
            return result
        elif isinstance(value, list):
            return [_process(item, False) for item in value]
        else:
            return None

    if not isinstance(manifest_dict, dict):
        return None
    return _process(manifest_dict, first_level)

