                # Example: spec 3.0 requires 'hardware' info
                hw = inventory.get('hardware')
                if not isinstance(hw, dict):
                    raise ValueError("Spec 3.0 requires a 'hardware' dictionary")
                if 'cpu' not in hw or 'memory' not in hw:
                    raise ValueError("'hardware' missing required 'cpu' or 'memory' fields")
            else:
                # Unknown spec_version: perform minimal sanity
                pass

        except Exception as exc:
            # Wrap any validation error into a ValueError for consistency
            raise ValueError(f"Inventory validation failed: {exc}") from exc

        return True

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then look at the ``type`` value to determine
    the specification version.  In the case that there is no ``type`` value or it
    isn't valid, the tests use ``self.spec_version`` that was previously set.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise ValueError("inventory must be a dictionary")

    # Extract spec version from the inventory if requested
    if extract_spec_version:
        inv_type = inventory.get("type")
        if isinstance(inv_type, str):
            # Accept simple numeric forms such as '1.0', '2', '3.4'
            try:
                parts = [int(p) for p in inv_type.split(".")]
                # Normalise to a string version
                if len(parts) == 1:
                    spec = f"{parts[0]}.0"
                else:
                    spec = f"{parts[0]}.{parts[1]}"
                # Only accept reasonable ranges; otherwise keep existing spec_version
                if 0 < parts[0] <= 10:
                    self.spec_version = spec
            except Exception:
                # Ignore invalid format, keep existing spec_version
                pass

    # Define the numeric value of the current spec version for comparison
    try:
        ver_nums = [int(p) for p in str(self.spec_version).split(".")]
    except Exception:
        ver_nums = [0]

    # Generic mandatory keys for every inventory
    mandatory_keys = {"name", "id"}
    missing = [k for k in mandatory_keys if k not in inventory]
    if missing:
        raise ValueError(f"Inventory missing mandatory keys: {missing}")

    # Extra validation based on specification version
    if ver_nums >= [2, 0]:
        if "components" not in inventory:
            raise ValueError("Inventory must include a 'components' key for spec_version >= 2.0")

    # If all checks pass, return the validated inventory (or a success flag)
    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Normalize inputs
        if not isinstance(manifest_files, (list, tuple)):
            raise TypeError(f"manifest_files must be a list or tuple, got {type(manifest_files)}")
        if not isinstance(digests_used, (set, list, tuple)):
            raise TypeError(f"digests_used must be a set, list, or tuple, got {type(digests_used)}")
        # Use lower‑case for consistent comparison
        digests_used_set = {str(d).lower() for d in digests_used}

        # Collect all digests that appear in the manifest
        manifest_digests = set()
        for idx, manifest_item in enumerate(manifest_files):
            if not isinstance(manifest_item, dict):
                raise TypeError(f"Each item in manifest_files must be a dict, "
                                f"but item {idx} is {type(manifest_item)}")
            # Assume digests are stored under a key named 'digests' or 'hashes'
            digests = None
            for key in ('digests', 'hashes', 'checksums', 'signature'):
                if key in manifest_item:
                    digests = manifest_item[key]
                    break
            if digests is None:
                continue  # No digest info to check for this item
            if isinstance(digests, dict):
                manifest_digests.update({str(k).lower() for k in digests.keys()})
            elif isinstance(digests, (list, tuple)):
                manifest_digests.update({str(d).lower() for d in digests})
            else:
                raise TypeError(f"Unexpected digest format for item {idx}: {type(digests)}")

        # Digests present in manifest but not marked as used
        unused_in_manifest = manifest_digests - digests_used_set
        # Digests marked as used but missing in manifest
        missing_in_manifest = digests_used_set - manifest_digests

        error_messages = []
        if unused_in_manifest:
            error_messages.append(
                f"Digests found in manifest but not used: {sorted(unused_in_manifest)}"
            )
        if missing_in_manifest:
            error_messages.append(
                f"Digests used but not present in manifest: {sorted(missing_in_manifest)}"
            )

        if error_messages:
            raise ValueError(" | ".join(error_messages))
        # If we reach here, all required digests are present and used properly.  ▪︎

        return None  # Explicitly return None for clarity only₫

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Collect all digests present in the manifest files
    present_digests = set()
    for mf in manifest_files:
        try:
            with open(mf, 'r', encoding='utf-8') as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith('#'):
                        continue
                    parts = line.split()
                    if parts:
                        present_digests.add(parts[0])
        except FileNotFoundError as e:
            raise RuntimeError(f"Manifest file '{mf}' not found.") from e
        except Exception as e:
            raise RuntimeError(f"Error reading manifest file '{mf}': {e}") from e

    # Determine the set of digests that are required/used
    if isinstance(digests_used, dict):
        used_digests = set(digests_used.keys())
    elif isinstance(digests_used, (set, list, tuple)):
        used_digests = set(digests_used)
    else:
        raise TypeError("digests_used must be a set, list, tuple, or dict")

    # Check for missing digests
    missing = used_digests - present_digests
    if missing:
        raise RuntimeError(
            f"The following required digests are missing from the manifest: {sorted(missing)}"
        )

    # Optionally warn about digests present but not used
    unused = present_digests - used_digests
    if unused:
        warning_msg = (
            f"The following digests are present in the manifest but not used: {sorted(unused)}"
        )
        if hasattr(self, "logger") and hasattr(self.logger, "warning"):
            self.logger.warning(warning_msg)
        else:
            # Fallback to standard error output
            try:
                import sys
                sys.stderr.write(warning_msg + "\n")
            except Exception:
                pass
    return None

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        if not isinstance(manifest_files, list):
            raise TypeError(f"manifest_files must be a list; got {type(manifest_files).__name__}")
