        if isinstance(digests_used, dict):
            digests_used = set(digests_used.keys())
        elif not isinstance(digests_used, set):
            # Try to convert to set
            try:
                digests_used = set(digests_used)
            except TypeError:
                raise TypeError(f"digests_used must be a set or dict; got {type(digests_used).__name__}")
        missing = []
        for entry in manifest_files:
            if not isinstance(entry, dict):
                continue  # skip invalid entries
            digest = entry.get("digest") or entry.get("etag")
            if not digest:
                continue  # skip entries without a digest
            if digest not in digests_used:
