def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate input types
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(version, (str, int)):
        raise TypeError("version must be a string or integer key")

    # Attempt to retrieve the version data
    try:
        version_info = inventory[version]
    except KeyError as exc:
        raise KeyError(f"Version {version!r} not found in inventory") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error accessing inventory: {exc}") from exc

    # Extract state mapping; fall back to empty dict if missing or malformed
    try:
        state = version_info.get('state', {})
        if not isinstance(state, dict):
            raise ValueError("state field must be a dictionary")
    except Exception as exc:
        raise ValueError(f"Invalid state format for version {version!r}: {exc}") from exc

    result = {}
    for logical_path, content in state.items():
        # Ensure logical_path is hashable
        try:
            hash(logical_path)
        except Exception as exc:
            raise ValueError(f"Logical path {logical_path!r} is unhashable: {exc}") from exc

        # Normalize content files to a set
        try:
            if isinstance(content, (set, list, tuple)):
                files = set(content)
            else:
                files = {content}
        except Exception as exc:
            # If any unexpected issue, skip this entry but log the error
            continue

        result[logical_path] = files

    return result

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    def _ensure_set(v):
        if isinstance(v, (set, frozenset)):
            return set(v)
        if isinstance(v, (list, tuple)):
            return set(v)
        if isinstance(v, str):
            return {v}
        raise TypeError(f"Unsupported content file type: {type(v)}")

    if inventory is None or not isinstance(inventory, dict):
        raise ValueError("Inventory must be a non-empty dictionary")
    if version not in inventory:
        raise ValueError(f"Version {version!r} not found in inventory")

    version_data = inventory[version]
    if not isinstance(version_data, dict):
        raise ValueError(f"Inventory data for version {version!r} must be a dictionary")

    # Try a few common keys for the logical path mapping
    mapping = None
    for key in ("logical_path_map", "file_map", "files", "paths"):
        if key in version_data:
            mapping = version_data[key]
            break
    if mapping is None:
        raise ValueError(f"No logical path map found for version {version!r}")

    # Ensure mapping is a dictionary; if list/tuple of (path, files) treat accordingly
    result = {}
    try:
        if isinstance(mapping, dict):
            for path, files in mapping.items():
                if not isinstance(path, str):
                    raise TypeError(f"Logical path must be a string, got {type(path)}")
                result[path] = _ensure_set(files)
        elif isinstance(mapping, (list, tuple)):
            for item in mapping:
                if not isinstance(item, (list, tuple)) or len(item) != 2:
                    raise ValueError("Logical path map list items must be [path, files]")
                path, files = item
                if not isinstance(path, str):
                    raise TypeError(f"Logical path must be a string, got {type(path)}")
                result[path] = _ensure_set(files)
        else:
            raise TypeError(f"Unsupported logical path map type: {type(mapping)}")
    except Exception as exc:
        raise ValueError(f"Error processing logical path map for version {version!r}: {exc}") from exc

    return result

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Return a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Normalize inventory to a mapping of version -> path mapping
    if isinstance(inventory, list):
        # Expect each item to be a dict with 'version' and 'paths'
        inv_by_version = {}
        for entry in inventory:
            try:
                v = entry.get("version")
                if v is None:
                    continue
                paths = entry.get("paths", {})
                if not isinstance(paths, dict):
                    continue
                inv_by_version[v] = paths
            except Exception:
                # Skip entries that don't match expected format
                continue
    elif isinstance(inventory, dict):
        inv_by_version = inventory
    else:
        # Unsupported inventory format
        return {}

    # Find all versions >= target version (to include duplicates)
    try:
        target_version = int(version)
    except Exception:
        try:
            target_version = float(version)
        except Exception:
            # If version can't be interpreted as numeric, use as key as is
            target_version = version

    # Build a sorted list of versions (keys) that are comparable
    # We'll filter out non-numeric versions if target is numeric
    def _key(v):
        if isinstance(v, (int, float)):
            return v
        try:
            return int(v)
        except Exception:
            try:
                return float(v)
            except Exception:
                return None

    sorted_versions = []
    for v in inv_by_version.keys():
        k = _key(v)
        if k is not None:
            sorted_versions.append((k, v))
    sorted_versions.sort(key=lambda kv: kv[0])

    # Filter versions that are >= target_version
    relevant_versions = [orig_v for k, orig_v in sorted_versions if k >= target_version]

    path_to_files = {}
    for rev in relevant_versions:
        paths = inv_by_version.get(rev, {})
        if not isinstance(paths, dict):
            continue
        for logical_path, content in paths.items():
            # Normalize content to a set of file paths
            if isinstance(content, (set, list, tuple)):
                files = set(content)
            else:
                files = {content}
            if logical_path not in path_to_files:
                path_to_files[logical_path] = set()
            path_to_files[logical_path].update(files)

    # Convert defaultdict back to regular dict
    result = {lp: set(files) for lp, files in path_to_files.items()}
    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inventory type
    if not isinstance(inventory, dict):
        raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")

    # Ensure the requested version exists
    if version not in inventory:
        raise KeyError(f"Version '{version}' not found in inventory")

    # This dictionary will store the result
    result = {}

    # Retrieve the data for the requested version
    version_data = inventory[version]

    # Two main possible structures for version_data:
    # 1. A dict mapping logical_path -> content_files (single item or iterable)
    # 2. An iterable of items each containing logical_path and content_file(s)

    # Helper to convert a content file(s) field into a set
    def to_set(item):
        if isinstance(item, (set, frozenset)):
            return set(item)
        if isinstance(item, (list, tuple)):
            return set(item)
        # Anything else treated as single file
        return {str(item)}

    # Case 1: version_data is a dict
    if isinstance(version_data, dict):
        for logical_path, content_files in version_data.items():
            # Logical path must be a string
            if not isinstance(logical_path, str):
                continue
            result[logical_path] = to_set(content_files)
        return result

    # Case 2: version_data is an iterable (not a dict)
    try:
        iterator = iter(version_data)
    except TypeError:
        raise TypeError(
            f"inventory[{version!r}] must be a dict or an iterable of items"
        )

    for item in iterator:
        # Attempt to retrieve logical_path and content_file(s)
        # Support dict items or objects with attributes
        logical_path = None
        content_field = None

        if isinstance(item, dict):
            logical_path = item.get("logical_path")
            content_field = item.get("content_file")
        else:
            # Attempt attribute access
            try:
                logical_path = getattr(item, "logical_path")
                content_field = getattr(item, "content_file")
            except AttributeError:
                continue

        if logical_path is None or content_field is None:
            continue

        # Convert to string if not already
        logical_path = str(logical_path)
        content_files = to_set(content_field)

        # Merge with any existing entries (duplicates allowed)
        if logical_path in result:
            result[logical_path].update(content_files)
        else:
            result[logical_path] = content_files

    return result

