        # re-raise as RuntimeError to indicate runtime failure
        raise RuntimeError(f"Failed to explore folder '{folder}': {exc}") from exc

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder does not exist: {folder}")

    result = {}
    try:
        for root, _, files in os.walk(folder):
            for filename in files:
                # Skip hidden files
                if filename.startswith('.'):
                    continue
                stem, ext = os.path.splitext(filename)
                # Determine if this file should be part of a group
                if ext.lower() == '.xml':
                    # Start a new group or extend existing
                    key = stem
                    if key not in result:
                        result[key] = []
                    # Store path relative to the root folder
                    rel_path = os.path.relpath(os.path.join(root, filename), folder)
                    result[key].append(rel_path)
                else:
                    # Associate non-xml file with existing XML group if names match
                    if stem in result:
                        rel_path = os.path.relpath(os.path.join(root, filename), folder)
                        result[stem].append(rel_path)
        # Optionally, sort file lists for consistency
        for key in result:
            result[key].sort()
    except Exception as e:
        raise RuntimeError(f"Error while exploring folder '{folder}': {e}") from e

    return result

