        xml_basenames = {}
        for entry in os.scandir(folder):
            if entry.is_file() and entry.name.lower().endswith('.xml'):
                base = os.path.splitext(entry.name)[0]
                xml_basenames[base] = entry.name

        # Group all files that share the same basename (ignoring extension)
        for entry in os.scandir(folder):
            if not entry.is_file():
                continue
            base = os.path.splitext(entry.name)[0]
            if base in xml_basenames:
                key = xml_basenames[base]  # e.g., 'sample.xml'
                package_dict.setdefault(key, []).append(entry.name)

        # Sort the file lists for deterministic ordering
        for key in package_dict:
            package_dict[key].sort()

    except Exception:
        # On any unexpected error, return an empty dict
        return {}

    return package_dict

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e retorna um dicionário contendo o
    tipo (`asset`, `rendition` ou `unknown`) e o caminho completo do arquivo.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        caminho completo do arquivo a ser analisado

    Returns
    -------
    dict
        dicionário com as chaves 'type', 'prefix' e 'path'
    """
    try:
        if not isinstance(file_path, str) or not file_path:
            return {'type': None, 'prefix': prefix, 'path': None}

        # Obtenha a extensão do arquivo (sem ponto e em minúsculas)
        parts = file_path.split('.')
        ext = parts[-1].lower() if len(parts) > 1 else ''

        # Definições de extensões para tipos conhecidos
        asset_exts = {'xml', 'json', 'jsonld', 'yml', 'yaml'}
        rendition_exts = {'jpg', 'jpeg', 'png', 'gif', 'tif', 'tiff', 'bmp'}

        if ext in asset_exts:
            file_type = 'asset'
        elif ext in rendition_exts:
            file_type = 'rendition'
        else:
            file_type = 'unknown'

        return {'type': file_type, 'prefix': prefix, 'path': file_path}
    except Exception:
        # Em caso de qualquer exceção, retorne valores nulos
        return {'type': None, 'prefix': prefix, 'path': file_path}

