                        item_str += f"  # type: {type(item).__name__}"
                    items.append(item_str)
                inner = ",\n".join(items)
                return f"{open_char}\n{inner}\n{prefix}{close_char}"
            elif isinstance(obj, str):
                return repr(obj)
            else:
                # Fallback to built‑in string conversion
                return repr(obj)

        # Start formatting from the current object
        result = _repr(self, indent)
        if debug:
            result += f"\n# debug: type={type(self).__name__}"
