        return f"<pretty error: {exc}>"

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate arguments
    if not isinstance(indent, int) or indent < 0:
        raise ValueError("indent must be a non-negative integer")
    if not isinstance(debug, bool):
        raise ValueError("debug must be a boolean")

    # Helper to format any value recursively
    def _format_value(value, level, visited):
        # Prevent infinite recursion
        obj_id = id(value)
        if obj_id in visited:
            return "<Recursion detected>"
        visited.add(obj_id)

        try:
            if isinstance(value, (str, int, float, bool)) or value is None:
                if debug:
                    return f"{repr(value)} ({type(value).__name__})"
                return repr(value)

            if isinstance(value, dict):
                return _format_dict(value, level, visited)

            if isinstance(value, (list, tuple, set)):
                return _format_sequence(value, level, visited)

            if hasattr(value, "__dict__"):
                return _format_dict(vars(value), level, visited)

            if hasattr(value, "__slots__"):
                slots = {slot: getattr(value, slot) for slot in value.__slots__ if hasattr(value, slot)}
                return _format_dict(slots, level, visited)

            # Fallback
            return repr(value)
        finally:
            visited.remove(obj_id)

    def _format_dict(d, level, visited):
        indent_str = " " * (level * 4)
        inner_indent_str = " " * ((level + 1) * 4)
        lines = []
        for k, v in d.items():
            val_str = _format_value(v, level + 1, visited)
            lines.append(f"{inner_indent_str}{k}: {val_str}")
        return "{\n" + "\n".join(lines) + f"\n{indent_str}}}"

    def _format_sequence(seq, level, visited):
        indent_str = " " * (level * 4)
        inner_indent_str = " " * ((level + 1) * 4)
        lines = []
        for v in seq:
            val_str = _format_value(v, level + 1, visited)
            lines.append(f"{inner_indent_str}{val_str}")
        return "[\n" + "\n".join(lines) + f"\n{indent_str}]"

    # Start formatting from the object's attributes
    if hasattr(self, "__dict__"):
        data = vars(self)
    elif hasattr(self, "__slots__"):
        data = {slot: getattr(self, slot) for slot in self.__slots__ if hasattr(self, slot)}
    else:
        return repr(self)

    # Use a set to track visited object ids for cycle detection
    visited_set = set()
    return _format_dict(data, indent, visited_set)

