    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    try:
        from sympy import And, Or, Not
    except Exception as exc:
        raise RuntimeError("sympy is required for absorption logic") from exc

    if not hasattr(args, "__iter__"):
        raise TypeError("absorb expects an iterable of expressions")

    new_exprs = []

    for expr in args:
        # Skip non-And/Or expressions
        if not isinstance(expr, (And, Or)):
            new_exprs.append(expr)
            continue

        # Helper to find absorption patterns in binary tree
        def apply_absorption(e):
            # e is an And or Or
            ops = e.args
            for idx, sub in enumerate(ops):
                if isinstance(sub, (And, Or)):
                    # Check if sub matches pattern with another operand
                    other = e.func(*[op for i, op in enumerate(ops) if i != idx])
                    # e could be And containing Or or And containing And ??
                    # We focus on patterns specified.

                    # For And: A & (A | B)
                    if isinstance(e, And) and isinstance(sub, Or):
                        # sub = Or(X, Y)
                        for X in sub.args:
                            if X in ops and X not in (sub,):
                                return X
                    # For Or: A | (A & B)
                    if isinstance(e, Or) and isinstance(sub, And):
                        for X in sub.args:
                            if X in ops and X not in (sub,):
                                return X
                    # Negative absorption for And: A & (~A | B)
                    if isinstance(e, And) and isinstance(sub, Or):
                        # check if sub contains Not and the other operand equal to some op
