                            if isinstance(op_sub, Not):
                                neg = op_sub.args[0]
                                if neg in ops:
                                    # Find B
                                    B_candidates = [arg for arg in sub.args if arg != op_sub]
                                    if B_candidates:
                                        return And(ops[ops.index(neg)], *B_candidates)
                    # Negative absorption for Or: A | (~A & B)
                    if isinstance(e, Or) and isinstance(sub, And):
                        for op_sub in sub.args:
                            if isinstance(op_sub, Not):
                                neg = op_sub.args[0]
