    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    # Ensure the registry exists
    registry = getattr(self, "_hook_registry", None)
    if registry is None:
        registry = {}
        setattr(self, "_hook_registry", registry)

    # Validate hook exists in the registry
    if hook not in registry:
        raise KeyError(f"Hook '{hook}' is not registered in the handler registry.")

    # Decorator that registers the function
    def decorator(func):
        if not callable(func):
            raise TypeError("Handler must be callable.")
        try:
            registry[hook].append(func)
        except Exception as exc:
            raise RuntimeError(f"Failed to register handler for hook '{hook}': {exc}") from exc
        return func

    return decorator

