def render(pieces, style):
    """Render the given version pieces into the requested style."""
    try:
        if pieces is None:
            raise ValueError("pieces cannot be None")

        # Normalise pieces into a list of strings or a dict for semver handling
        if isinstance(pieces, dict):
            normalized = {k: str(v) for k, v in pieces.items() if v is not None}
        elif isinstance(pieces, (list, tuple)):
            normalized = [str(v) for v in pieces if v is not None]
        else:
            try:
                iterable = list(pieces)
                normalized = [str(v) for v in iterable if v is not None]
            except TypeError:
                raise TypeError("pieces must be a list, tuple, dict, or iterable")

        style_lower = (style or "").lower()
        if style_lower == "" or style_lower == "semver":
            # Assemble a semantic version string
            if isinstance(normalized, dict):
                major = normalized.get("major")
                minor = normalized.get("minor")
                patch = normalized.get("patch")
                prerelease = normalized.get("prerelease")
                build = normalized.get("build")
            else:
                major = normalized[0] if len(normalized) > 0 else None
                minor = normalized[1] if len(normalized) > 1 else None
                patch = normalized[2] if len(normalized) > 2 else None
                prerelease = normalized[3] if len(normalized) > 3 else None
                build = normalized[4] if len(normalized) > 4 else None

            base_parts = [p for p in (major, minor, patch) if p is not None]
            if not base_parts:
