    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands) + list(args)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    # Prepare environment
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError("env must be a dict mapping environment variables")
        merged_env = os.environ.copy()
        merged_env.update(env)
    else:
        merged_env = None

    # Optional verbosity
    if verbose:
        try:
            printed = shlex.join(cmd_list)
        except AttributeError:  # fallback for older Python versions
            printed = ' '.join(shlex.quote(part) for part in cmd_list)
        print(f"Running command: {printed}")

    # Execute
    try:
        result = subprocess.run(
            cmd_list,
            cwd=cwd,
