            capture_output=True,
            check=True,
            stderr=subprocess.DEVNULL if hide_stderr else None
        )
        return result
    except FileNotFoundError as e:
        raise RuntimeError(f"Executable '{cmd_list[0]}' not found") from e
    except subprocess.CalledProcessError as e:
        # Provide detailed error
        raise RuntimeError(
            f"Command '{' '.join([shlex.quote(part) for part in e.cmd])}' "
            f"failed with exit code {e.returncode}\n"
            f"Stdout: {e.output}\n"
            f"Stderr: {e.stderr}"
