def register_vcs_handler(vcs, method=None):
    """
    Create decorator to mark a method as the handler of a VCS.

    This function can be used either as a decorator:

        @register_vcs_handler('git')
        def git_handler(...):
            ...

    or called directly to register an existing function:

        register_vcs_handler('git', git_handler)
    """
    # Ensure a registry exists on the function
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}
    registry = register_vcs_handler._registry

    def _register(func):
        if not isinstance(vcs, str) or not vcs:
            raise ValueError(f"VCS name must be a non-empty string, got {vcs!r}")
        if not callable(func):
            raise ValueError(f"Handler must be callable, got {type(func).__name__}")
        registry[vcs] = func
        return func

    # If method argument is provided, register immediately
    if method is not None:
        return _register(method)

    # Else return the decorator that expects the function
    return _register

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    # Validate inputs
    if not isinstance(vcs, str) or not vcs:
        raise ValueError("vcs must be a non-empty string")
    if not isinstance(method, str) or not method:
        raise ValueError("method must be a non-empty string")

    def decorator(func):
        if not callable(func):
            raise TypeError("Registered handler must be callable")

        # Use an attribute on the outer function to store the registry
        registry = getattr(register_vcs_handler, "_registry", {})

        key = (vcs, method)
        if key in registry:
            raise ValueError(
                f"A handler for vcs={vcs!r} and method={method!r} is already registered."
            )

        registry[key] = func
        # Persist the updated registry
        register_vcs_handler._registry = registry

        return func

    return decorator

