                if hasattr(obj, "digest") and callable(getattr(obj, "digest")):
                    actual_digest = obj.digest()
                elif hasattr(obj, "compute_digest") and callable(getattr(obj, "compute_digest")):
                    actual_digest = obj.compute_digest()
                else:
                    actual_digest = None

                # Compare with a stored expected value if present.
                if actual_digest is not None:
                    expected_digest = getattr(obj, "expected_digest", None)
                    if expected_digest is not None and actual_digest != expected_digest:
                        obj_is_valid = False
                        if show_warnings:
                            print(f"Warning: digest mismatch for {obj!r}: expected {expected_digest}, got {actual_digest}")
            except Exception as exc:
                obj_is_valid = False
                if show_warnings:
                    print(f"Warning: digest exception for {obj!r}: {exc}")

        # Count good objects.
        if obj_is_valid:
            good_objects += 1

        # Queue children for traversal.  Support common patterns.
        for child in getattr(obj, "children", []):
            if child is not None:
                stack.append(child)
        # If children attribute is missing, try to iterate the object itself (e.g., a list of leaf nodes).
        if not getattr(obj, "children", None):
            try:
                for sub in obj:
                    stack.append(sub)
            except TypeError:
                pass

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Ensure the root path is defined and is a string
    if not hasattr(self, "root_path") or not isinstance(self.root_path, str):
        raise AttributeError("An instance attribute 'root_path' must be set to a string path before calling initialize.")
    root = self.root_path

    try:
        # Create root directory if it doesn't exist
        os.makedirs(root, exist_ok=True)
    except OSError as exc:
        raise RuntimeError(f"Cannot create OCFL root directory '{root}': {exc}") from exc

    # Subdirectories required for an OCFL repository
    objects_dir = os.path.join(root, "objects")
    work_dir = os.path.join(root, "work")

    try:
        os.makedirs(objects_dir, exist_ok=True)
        os.makedirs(work_dir, exist_ok=True)
    except OSError as exc:
        raise RuntimeError(f"Cannot create required subdirectories in OCFL root: {exc}") from exc

    # Create minimal metadata file if it does not exist
    root_meta = os.path.join(root, "ocfl-root.json")
    if not os.path.exists(root_meta):
        try:
            with open(root_meta, "w", encoding="utf-8") as f:
                f.write('{"ocfl_version":"1.0"}')
        except OSError as exc:
            raise RuntimeError(f"Cannot write metadata file '{root_meta}': {exc}") from exc

    # Initialization successful
    return 1

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    version = version.strip()
    if not version:
        raise ValueError("empty version string")

    parts = version.split('.')
    if not all(part.isdigit() for part in parts):
        raise ValueError("version must contain only numeric components separated by '.'")

    # Increment the last numeric component
    last = parts[-1]
    width = len(last)
    try:
        num = int(last) + 1
    except Exception as exc:
        raise ValueError("invalid numeric value in version") from exc

    new_last = str(num)
    # Preserve original padding if the new number is shorter
    if len(new_last) < width:
        new_last = new_last.zfill(width)

    return '.'.join(parts[:-1] + [new_last])

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("Version must be a string.")
    ver = version.strip()
    if not ver:
        raise ValueError("Version string cannot be empty.")

    parts = ver.split(".")
    # Find the last numeric part
    idx = None
    for i in range(len(parts)-1, -1, -1):
        if parts[i].isdigit():
            idx = i
            break
    if idx is None:
        raise ValueError("No numeric part found in version string.")

    num_part = parts[idx]
    try:
        new_value = int(num_part) + 1
    except ValueError:
        raise ValueError("Numeric part could not be converted to integer.")

    # Preserve leading zeros if present
    new_num_str = str(new_value)
    if num_part.startswith("0") and len(num_part) > 1:
        new_num_str = new_num_str.zfill(len(num_part))

    parts[idx] = new_num_str
    return ".".join(parts)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    # Determine the root directory that contains the inventories
    root_dir = getattr(self, "root_path", None)
    if root_dir is None:
        root_dir = getattr(self, "base_dir", None)
    if root_dir is None:
        raise RuntimeError("Cannot determine root directory for inventories.")

    # Load the root inventory
    root_inventory_path = os.path.join(root_dir, "inventory.json")
    if not os.path.isfile(root_inventory_path):
        raise FileNotFoundError(f"Root inventory not found at {root_inventory_path}.")
    try:
        with open(root_inventory_path, "r", encoding="utf-8") as f:
            root_inventory = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Root inventory JSON is malformed: {e}")

    differing_digests = {}

    # Iterate over each version directory in order
    for v_dir in version_dirs:
        inv_path = os.path.join(root_dir, v_dir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory in version directory '{v_dir}' (expected {inv_path}).")
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except json.JSONDecodeError as e:
            raise ValueError(f"Inventory JSON malformed in {inv_path}: {e}")

        # Verify that the version inventory is a mapping of paths to digests
        if not isinstance(inv, dict):
            raise TypeError(f"Inventory in {inv_path} must be a JSON object mapping file paths to digests.")

        # Compare each digest against the root inventory
        for rel_path, digest in inv.items():
            # The root must also contain the file; if not, it's an error
            if rel_path not in root_inventory:
                raise ValueError(f"File {rel_path!r} present in version '{v_dir}' but not found in root inventory.")
            root_digest = root_inventory[rel_path]
            if digest != root_digest:
                differing_digests[rel_path] = {"root_digest": root_digest, "version_digest": digest}

        # Ensure that the inventory does not contain unknown files (outside root)
        unexpected = set(inv.keys()) - set(root_inventory.keys())
        if unexpected:
            raise ValueError(f"Inventory in {v_dir} contains unknown files: {sorted(unexpected)}")

    # Record the differing digests for later validation
    self._differing_digests =

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure root inventory is available
    if not hasattr(self, "root_inventory") or self.root_inventory is None:
        raise ValueError("Root inventory not loaded. Cannot validate version inventories.")
    # Prepare structures
    self.inventory_differences = []          # List of discrepancies
    self.validation_result_inventories = {}  # Mapping of dir -> inventory dict
    known_items = set()

    for idx, dir_path in enumerate(version_dirs, start=1):
        inventory_file = os.path.join(dir_path, "inventory.json")
        if not os.path.isfile(inventory_file):
            raise ValueError(f"Missing inventory file in version directory '{dir_path}'. Expected '{inventory_file}'.")
        try:
            with open(inventory_file, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory JSON from '{inventory_file}': {exc}")

        if not isinstance(inv, dict):
            raise ValueError(f"Inventory file '{inventory_file}' must contain a JSON object (key-value map).")

        # Validate that inventory contains at least all items from previous versions
        if known_items:
            missing_items = known_items - inv.keys()
            if missing_items:
                raise ValueError(
                    f"Inventory in '{dir_path}' is missing items present in earlier inventories: {sorted(missing_items)}"
                )

        # Record any digest differences compared to the root inventory
        for item, digest in inv.items():
            root_digest = self.root_inventory.get(item)
            if root_digest is not None and digest != root_digest:
                self.inventory_differences.append(
                    {
                        "item": item,
                        "version": idx,
                        "root_digest": root_digest,
                        "version_digest": digest,
                    }
                )

        # Update known items set with all items seen so far
        known_items.update(inv.keys())

        # Store the inventory for potential later use
        self.validation_result_inventories[dir_path] = inv

    # If we reach here, all inventories validated successfully. No return needed.

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    try:
        p = str(path)
    except Exception as e:
        return f"invalid path: {e}"
    if not os.path.exists(p):
        return f"path does not exist: {p}"
    if os.path.isfile(p):
        return "file"
    if not os.path.isdir(p):
        return f"not a file or directory: {p}"
    try:
        entries = os.listdir(p)
    except Exception as e:
        return f"cannot list directory: {e}"
    # Count files that match the "0=*" pattern
    namaste_files = []
    for entry in entries:
        if entry.startswith("0="):
            full = os.path.join(p, entry)
            if os.path.isfile(full):
                namaste_files.append(entry)
    count = len(namaste_files)
    if count == 0:
        return "no Namaste files found"
    if count == 1:
        return "root"
    # When more than one Namaste file exists, likely an object
    return "object"

def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params
        Add the provided bug_ids to the parameters dictionary used to query
        Bugzilla. The method ensures that the `params` argument is a dictionary
        and that `bug_ids` can be interpreted as an iterable of integers or
        strings. It returns a new dictionary that contains all original
        parameters plus the key ``'ids'`` set to the list of bug IDs.
        Invalid types raise a ``TypeError``.
        """
        # Validate params is a dict
        if not isinstance(params, dict):
            raise TypeError(f"'params' must be a dictionary, got {type(params).__name__}")

        # Convert bug_ids to a list
        if isinstance(bug_ids, (list, tuple, set)):
            bug_id_list = list(bug_ids)
        elif isinstance(bug_ids, (int, str)):
            bug_id_list = [bug_ids]
        else:
            raise TypeError(f"'bug_ids' must be an int, str, list, tuple, or set, got {type(bug_ids).__name__}")

        # Ensure bug IDs are hashable and reasonable
        cleaned_ids = []
        for bid in bug_id_list:
            try:
                # Accept ints or strings that represent ints
                if isinstance(bid, int):
                    cleaned_ids.append(bid)
                elif isinstance(bid, str) and bid.isdigit():
                    cleaned_ids.append(int(bid))
                elif isinstance(bid, str):
                    cleaned_ids.append(bid)
                else:
                    raise ValueError
            except Exception:
                raise ValueError(f"Invalid bug ID value: {bid!r}") from None

        # Create a new params dict to avoid mutating the caller's dict
        new_params = params.copy()
        new_params['ids'] = cleaned_ids
        return new_params

