        if isinstance(bug_ids, (int, str)):
            bug_ids = [bug_ids]
        elif isinstance(bug_ids, list):
            pass
        else:
            raise TypeError(f"bug_ids must be an int, str, or list, got {type(bug_ids).__name__}")

        # Convert all ids to integers (ignore unconvertible entries)
        converted_ids = []
        for bid in bug_ids:
            try:
                converted_ids.append(int(bid))
