    '''
    Merge a list of (ScalarNode, Node) tuples, deep‑merging mapping nodes with identical keys.
    '''
    if not isinstance(nodes, list):
        return nodes

    merged = {}
    for key_node, val_node in nodes:
        # The key for the dictionary is the ScalarNode's value
        key = getattr(key_node, 'value', None)
        if key is None:
            # If we cannot determine the key, skip this entry
            continue

        if key in merged:
            existing_key_node, existing_val_node = merged[key]
            # If both are MappingNode, deep merge
            if hasattr(existing_val_node, 'tag') and hasattr(val_node, 'tag'):
                try:
                    # Assume MappingNode when value attribute is a list of pairs
                    if isinstance(existing_val_node.value, list) and isinstance(val_node.value, list):
                        merged_value = deep_merge_nodes(existing_val_node.value + val_node.value)
                        merged_node = type(val_node)(
                            tag=val_node.tag,
                            value=merged_value
                        )
                        merged[key] = (existing_key_node, merged_node)
                        continue
                except Exception:
                    # Fall back to simple replace
                    pass
            # For non‑mapping values or failed merge, the later wins
            merged[key] = (key_node, val_node)
        else:
            merged[key] = (key_node, val_node)

    return list(merged.values())

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a
    space-separated string.
    """
    # Basic validation of the parser object
    if parser is None or not hasattr(parser, 'actions'):
        raise TypeError("Expected an argparse.ArgumentParser instance")

    flags = []
    for action in parser.actions:
        try:
            # Optional arguments expose their option strings
            if action.option_strings:
                flags.extend(action.option_strings)
            else:
                # Positional arguments generally lack option strings;
                # use the destination name as the flag if present
                dest = getattr(action, 'dest', None)
                if dest:
                    flags.append(dest)
        except Exception:
            # Silently ignore actions that do not follow the expected interface
            continue

    return ' '.join(flags)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Basic validation
    try:
        actions = parser._actions  # internal list of argparse actions
    except AttributeError:
        raise TypeError("Provided object does not appear to be an argparse.ArgumentParser")

    flags = []
    for action in actions:
        # Some actions (e.g., positional arguments) may have no option_strings
        if hasattr(action, 'option_strings'):
            flags.extend(action.option_strings)
    return ' '.join(flags)

