    Merge a list of YAML nodes with potentially duplicate keys, performing a deep merge
    on MappingNode values. If duplicate keys have non-mapping values, the last value wins.
    The function works with ruamel.yaml node objects.
    """
    # Utility to check if a node is a MappingNode
    def is_mapping_node(node):
        return hasattr(node, "tag") and node.tag == "tag:yaml.org,2002:map"

    # Merge two mapping node values (both assumed to be MappingNode)
    def merge_mappings(old_map, new_map):
        # Build ordered dict from the old mapping value
        from collections import OrderedDict

        def mapping_to_dict(m):
            od = OrderedDict()
            for k_node, v_node in m.value:
                k = getattr(k_node, "value", None)
                od[k] = (k_node, v_node)
            return od

        old_dict = mapping_to_dict(old_map)
        new_dict = mapping_to_dict(new_map)

        # Merge new_dict into old_dict
        for k, (nk_node, nv_node) in new_dict.items():
            if k in old_dict:
                _, ov_node = old_dict[k]
                if is_mapping_node(ov_node) and is_mapping_node(nv_node):
                    merged_val = merge_mappings(ov_node, nv_node)
                else:
                    # last wins
                    merged_val = nv_node
                old_dict[k] = (nk_node, merged_val)
            else:
                old_dict[k] = (nk_node, nv_node)

        # Reconstruct mapping node value list preserving order
        merged_value_list = [(k_node, v_node) for k_node, v_node in old_dict.values()]
        return type(old_map)(tag=old_map.tag, value=merged_value_list)

    # Main merge logic
