                merged_val = merge_mappings(old_val_node, val_node)
            else:
                merged_val = val_node
            merged_dict[key] = (merged_dict[key][0], merged_val)  # keep original key node
        else:
            merged_dict[key] = (key_node, val_node)

    # Preserve order of first appearance of keys
    if not nodes:
        return []

    # Determine order based on first appearance
    seen = set()
    ordered_result = []
