def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of strings")
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dictionary mapping names to ArgumentParser objects")

    parsed = {}
    remaining_by_parser = {}

    for name, parser in subparsers.items():
        if not hasattr(parser, "parse_known_args"):
            raise TypeError(f"Subparser '{name}' does not have a 'parse_known_args' method")
        try:
            ns, rem = parser.parse_known_args(unparsed_arguments)
        except Exception:
            # In the unlikely event of a parsing error, fall back to an empty namespace
            ns = None
            rem = list(unparsed_arguments)
        parsed[name] = ns
        remaining_by_parser[name] = rem

    # Compute the intersection of remaining args across all subparsers
    if remaining_by_parser:
        sets_of_remaining = [set(rem) for rem in remaining_by_parser.values()]
        intersection_set = set.intersection(*sets_of_remaining)
        remaining = [arg for arg in unparsed_arguments if arg in intersection_set]
    else:
        remaining = []

    return parsed, remaining

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types
    if response is None:
        raise ValueError("Response cannot be None.")
    if not isinstance(response, list):
        raise ValueError(f"Response must be a list, got {type(response).__name__}.")
    if not isinstance(max_results, int):
        raise ValueError(f"max_results must be an integer, got {type(max_results).__name__}.")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer.")

    # Generator that yields slices of the list
    def _generator(data, chunk):
        for start in range(0, len(data), chunk):
            yield data[start:start + chunk]

    return _generator(response, max_results)

