    match = re.fullmatch(r'([0-9]+(?:\.[0-9]+)?)\s*([a-zA-Z]*)', size)
    if not match:
        raise ValueError(f"invalid size format: {size!r}")

    number_str, unit = match.groups()
    try:
        number = float(number_str)
    except ValueError as exc:
        raise ValueError(f"invalid numeric value: {number_str!r}") from exc

    if not unit:
        return int(round(number))

    unit = unit.lower()
    base_units = {'k': 1, 'm': 2, 'g': 3, 't': 4, 'p': 5, 'e': 6}

    # Detect binary units (e.g., Ki, Mi, Gi)
    if unit.endswith('i'):
        base = unit[:-1]
        exp = base_units.get(base)
        if exp is None:
            raise ValueError(f"unknown size unit: {unit!r}")
        multiplier = 1024 ** exp
    else:
        # Strip common trailing 'b' or 'bytes' suffixes
        if unit.endswith('bytes'):
            base = unit[:-5]
        elif unit.endswith('b'):
            base = unit[:-1]
        else:
            base = unit

        exp = base_units.get(base)
        if exp is None:
            raise ValueError(f"unknown size unit: {unit!r}")
        multiplier = 1000 ** exp

    return int(round(number * multiplier))

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
