    """
    if dicts is None:
        raise TypeError("Input 'dicts' cannot be None")
    result = {}
    try:
        iterator = iter(dicts)
    except TypeError as e:
        raise TypeError(f"Input 'dicts' must be an iterable of dictionaries; got {type(dicts).__name__}") from e
    for d in iterator:
        if not isinstance(d, dict):
            raise TypeError(f"Expected each element to be a dict; got {type(d).__name__}")
        for key, value in d.items():
            if key in result:
                try:
                    result[key] += value
                except Exception as exc:
                    raise TypeError(f"Error summing values for key '{key}': {result[key]} + {value}") from exc
            else:
                result[key] = value
    return result

