def was_processed(processed, path_name, verbose):
    """
    Check if a file or directory has already been processed.

    To prevent recursion, expand the path name to an absolution path
    call this function with a set that will store all the entries and
    the entry to test. If the entry is already in the set, report the issue
    and return ``True``. Otherwise, add the entry to the set and return
    ``False`` to allow the path to be processed.
    """
    # Validate inputs
    if processed is None:
        raise ValueError("processed set must not be None")
    if not isinstance(processed, set):
        raise TypeError("processed must be a set")
    if path_name is None:
        raise ValueError("path_name must not be None")
    if not isinstance(path_name, str):
        raise TypeError("path_name must be a string")
    if not isinstance(verbose, bool):
        raise TypeError("verbose must be a boolean")

    try:
        # Use os.path.abspath to get a canonical absolute path
        abs_path = os.path.abspath(path_name)
    except Exception as exc:
        if verbose:
            print(f"[ERROR] Could not resolve path '{path_name}': {exc}")
        raise

    if abs_path in processed:
        if verbose:
            print(f"[INFO] Already processed: {abs_path}")
        return True

    processed.add(abs_path)
    return False

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list) or len(alphabet) == 0:
        raise ValueError("alphabet must be a non-empty list")
    for idx, char in enumerate(alphabet):
        if not isinstance(char, str):
            raise TypeError(f"alphabet element at index {idx} is not a string")
        if len(char) != 1:
            raise ValueError(f"alphabet element at index {idx} must be a single character")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet elements must be unique")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer or None")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    base = len(alphabet)
    neg = number < 0
    n = -number if neg else number

    # Special case for zero
    if n == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while n > 0:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()

    # Apply padding if necessary
    if padding is not None and padding > len(digits):
        pad_count = padding - len(digits)
        digits = [alphabet[0]] * pad_count + digits

    result = ''.join(digits)
    if neg:
        result = '-' + result
    return result

