def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError('subclasses() requires a class')
    subs = set()
    for sub in cls.__subclasses__():
        subs.add(sub)
        subs.update(subclasses(sub))
    return subs

def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError(f"subclasses() expects a class, got {cls!r}")
    try:
        initial_subclasses = cls.__subclasses__()
    except Exception as exc:
        raise TypeError(f"Could not retrieve subclasses of {cls!r}: {exc}") from exc

    result = set()
    stack = list(initial_subclasses)
    while stack:
        sub = stack.pop()
        if sub not in result:
            result.add(sub)
            try:
                stack.extend(sub.__subclasses__())
            except Exception:
                # Some subclass objects might not expose __subclasses__ reliably; ignore them.
                pass
    return result

