            raise ValueError(f"alphabet element '{sym}' is not a single character")
        symbol_to_value[sym] = idx

    # Empty string is not a valid representation
    if not string:
        raise ValueError("input string is empty")

    value = 0
    for ch in string:
        if ch not in symbol_to_value:
            raise ValueError(f"invalid character '{ch}' in input string; expected one of {alphabet}")
        value = value * base + symbol_to_value[ch]

    return value

