def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    # Verify the input is a mapping
    if not isinstance(item, dict):
        raise TypeError("regex_dict requires a dictionary as input")
    result = {}
    for key, value in item.items():
        try:
            # Only convert keys that are strings containing a wildcard '*'
            if isinstance(key, str) and '*' in key:
                # Replace '*' with regex equivalent and escape other characters
                regex_key = '^' + re.escape(key.replace('*', '.*')) + '$'
                result[regex_key] = value
            else:
                # Preserve key as is if it doesn't fit the pattern
                result[key] = value
        except Exception:
            # On any error with the key, preserve original key/value
            result[key] = value
    return result

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

