    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError("regex_dict expects a dictionary input")
    result = {}
    for k, v in item.items():
        try:
            key_str = str(k)
        except Exception:
            # if key cannot be converted to string, keep it as is
            new_key = k
        else:
            if '*' in key_str:
                # Escape all regex special characters, then replace escaped '*'
                escaped = re.escape(key_str)
                # Replace escaped '*' back to wildcards
                pattern = escaped.replace(r'\*', '.*')
                # Anchor the pattern to match the whole string
                new_key = re.compile(f'^{pattern}$')
            else:
                new_key = k
        result[new_key] = v
    return result

