def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Validate input
    if not isinstance(s, str):
        raise TypeError(f"expected a string, got {type(s).__name__}")

    # Resolve platform flag
    try:
        if platform == 'this':
            import os
            # os.name: 'nt' on Windows, 'posix' on POSIX
            posix_mode = os.name != 'nt'
        elif platform in (1, 'posix', 'POSIX', 'POSIX'):
            posix_mode = True
        elif platform in (0, 'windows', 'cmd', 'CMD'):
            posix_mode = False
        else:
            raise ValueError(f"invalid platform value: {platform!r}")
    except Exception as exc:
        raise ValueError(f"Error determining platform: {exc}") from exc

    # Use shlex for robust parsing according to platform
    try:
        import shlex
        return shlex.split(s, posix=posix_mode)
    except ValueError as exc:
        # Re-raise with clearer context
        raise ValueError(f"failed to parse command: {exc}") from exc
    except Exception as exc:
        # Unexpected errors
        raise RuntimeError(f"unexpected error during split: {exc}") from exc

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not isinstance(s, str):
        raise TypeError("input must be a string")
    import sys, os, re
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    if platform == 1:  # POSIX
        pattern = re.compile(
            r'''(?:"(?P<dq>[^"]*)"|'(?P<sq>[^']*)'|(?P<word>\S+))''',
            re.VERBOSE,
        )
        tokens = []
        i = 0
        length = len(s)
        while i < length:
            # Skip leading whitespace
            while i < length and s[i].isspace():
                i += 1
            if i >= length:
                break
            m = pattern.match(s, i)
            if not m:
                # No quoted token; consume until next whitespace
                j = i
                while j < length and not s[j].isspace():
                    j += 1
                tokens.append(s[i:j])
                i = j
            else:
                if m.group('dq') is not None:
                    tokens.append(m.group('dq'))
                elif m.group('sq') is not None:
                    tokens.append(m.group('sq'))
                else:
                    tokens.append(m.group('word'))
                i = m.end()
        return tokens
    elif platform == 0:  # Windows
        # Use shlex in non‑POSIX mode for Windows quoting rules
        try:
            import shlex
            return shlex.split(s, posix=False)
        except Exception:
            # Fallback: simple split on whitespace, strip surrounding quotes
            parts = s.split()
            out = []
            for p in parts:
                if p.startswith('"') and p.endswith('"'):
                    out.append(p[1:-1].replace('""', '"'))
                else:
                    out.append(p)
            return out
    else:
        raise ValueError("unknown platform argument")

