def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys, os
    if not isinstance(s, str):
        raise TypeError("split() argument 's' must be a string")
    if platform == 'this':
        platform = 0 if os.name == 'nt' else 1
    if platform not in (0, 1):
        raise ValueError("platform must be 'this', 0 (Windows) or 1 (POSIX)")
    argv = []
    i, n = 0, len(s)
    while i < n:
        # skip leading whitespace
        while i < n and s[i].isspace():
            i += 1
        if i >= n:
            break
        token = []
        in_single = False
        in_double = False
        escape = False
        while i < n:
            c = s[i]
            if escape:
                # backslash escape – keep the following character as literal
                token.append(c)
                escape = False
            elif c == '\\':
                if platform == 0 and not in_double:
                    # In Windows cmd, backslashes are literal unless
                    # preceding a quote; treat as escape for simplicity
                    escape = True
                else:
                    escape = True
            elif c == '"' and not in_single:
                in_double = not in_double
            elif c == "'" and not in_double:
                in_single = not in_single
            elif c.isspace() and not in_single and not in_double:
                break
            else:
                token.append(c)
            i += 1
        argv.append(''.join(token))
    return argv

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """
    Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    try:
        # Resolve the temporary extraction directory
        tmp_dir = PosixPath(tmp_path)
        if not tmp_dir.is_absolute():
            tmp_dir = tmp_dir.resolve()
        # Determine extraction target name
        if filename:
            target_name = filename
        else:
            # For compound extensions like .tar.gz, strip them
            stem = PosixPath(archive_path).stem
            if stem.endswith((".tar",)):
                target_name = PosixPath(archive_path).stem
            else:
                # Attempt to remove common compressed suffixes
                for suffix in (".tar.gz", ".tgz", ".tar.bz2", ".tbz2", ".zip"):
                    if stem.lower().endswith(suffix):
                        target_name = stem[: -len(suffix)]
                        break
                else:
                    target_name = stem
        extract_dir = tmp_dir / target_name
        extract_dir.mkdir(parents=True, exist_ok=True)

        # Decide extraction method based on extension
        archive = PosixPath(archive_path)
        lower_name = archive.name.lower()
        if lower_name.endswith(".zip"):
            cmd = ["unzip", "-q", archive_path, "-d", str(extract_dir)]
        elif lower_name.endswith((".tar.gz", ".tgz")):
            cmd = ["tar", "-xzf", archive_path, "-C", str(extract_dir)]
        elif lower_name.endswith((".tar.bz2", ".tbz2")):
            cmd = ["tar", "-xjf", archive_path, "-C", str(extract_dir)]
        elif lower_name.endswith(".tar"):
            cmd = ["tar", "-xf", archive_path, "-C", str(extract_dir)]
        else:
            raise ValueError(f"Unsupported archive format for file: {archive_path}")

        # Execute extraction
        subprocess.run(cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        # Return a file:// URL pointing to the extracted repository directory
        return f"file://{extract_dir.resolve()}"
    except Exception as exc:
        raise RuntimeError(f"Failed to extract archive '{archive_path}': {exc}") from exc

def addignored(ignored):
    '''Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        # Retrieve ignored files from the current git repository
        output = subprocess.check_output(
            ['git', 'ls-files', '-i', '--exclude-standard'],
            universal_newlines=True,
            stderr=subprocess.DEVNULL
        )
        # Split into lines, filter out any empty entries, and sort
        files = sorted([f for f in output.splitlines() if f.strip()])
        # Return a comma‑separated string of file names
        return ','.join(files)
    except (subprocess.CalledProcessError, FileNotFoundError):
        # If git is not available or this is not a git repo, return an empty string
        return ''

def addignored(ignored):
    '''Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    # Validate input
    if not isinstance(ignored, str):
        return ''
    try:
        # Run git command to list ignored files
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            cwd=ignored,
            stderr=subprocess.DEVNULL
        )
        # Decode and split into lines
        files = output.decode('utf-8', errors='ignore').splitlines()
        # Filter out any empty lines and sort
        ignored_files = sorted(f for f in files if f.strip())
        return ','.join(ignored_files)
    except (subprocess.CalledProcessError, FileNotFoundError, OSError):
        # In case git is not available or command fails, return empty string
        return ''

def match(filename):
    """
    Check if the filename is a type that this module supports

    Args:
        filename: Filename to match
    Returns:
        False if not a match, True if supported
    """
    try:
        if not isinstance(filename, str) or not filename:
            return False
        _, ext = os.path.splitext(filename)
        supported = {'.txt', '.csv', '.json', '.xml'}
        return ext.lower() in supported
    except Exception:
        return False

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if isinstance(frequency, str):
        if frequency.strip().lower() == 'always':
            return None
    else:
        raise ValueError("frequency must be a string or None")
    if not isinstance(frequency, str):
        raise ValueError("frequency must be a string")
    import re
    s = frequency.strip()
    match = re.match(r'^(\d+)\s+(\w+)$', s)
    if not match:
        raise ValueError(f"cannot parse frequency '{frequency}'")
    amount = int(match.group(1))
    unit = match.group(2).lower()
    # Normalize unit to singular form
    if unit.endswith('s'):
        unit = unit[:-1]
    unit_map = {
        'day': 'days',
        'week': 'weeks',
        'hour': 'hours',
        'minute': 'minutes',
        'second': 'seconds',
    }
    if unit not in unit_map:
        raise ValueError(f"unknown unit '{unit}' in frequency '{frequency}'")
    kwargs = {unit_map[unit]: amount}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Ensure host is a string
    if not isinstance(host, str):
        return False
    host = host.strip()
    if not host:
        return False

    # Quick check for the literal "localhost"
    if host.lower() == "localhost":
        return True

    try:
        # Resolve host to all addresses
        for res in socket.getaddrinfo(host, None):
            sockaddr = res[4]
            if not sockaddr:
                continue
            ip = sockaddr[0]
            # IPv4 loopback check (127.0.0.0/8)
            if ":" not in ip:
                if ip.startswith("127."):
                    return True
            else:
                # IPv6 loopback check
                if ip.lower() == "::1":
                    return True
    except socket.gaierror:
        # Hostname could not be resolved – not localhost
        return False
    except Exception:
        # Any unexpected error treated as non-local
        return False

    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        infos = socket.getaddrinfo(host, None)
    except (socket.gaierror, socket.error):
        return False
    for info in infos:
        # info[4] is the sockaddr; for IPv4 it's (address, port),
        # for IPv6 it's (address, port, flow info, scope)
        try:
            addr = info[4][0]
        except (IndexError, TypeError):
            continue
        # Check for common IPv4 loopback
        if addr.startswith('127.'):
            return True
        # Check for IPv6 loopback
        if addr == '::1':
            return True
    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str) or not host:
        return False
    try:
        # Resolve the hostname or IP address; the port is irrelevant (None)
        address_info = socket.getaddrinfo(host, None)
    except (socket.gaierror, UnicodeError, ValueError):
        # Host could not be resolved or invalid format
        return False

    for family, _, _, _, sockaddr in address_info:
        try:
            if family == socket.AF_INET:
                # IPv4: only the loopback address is considered local
                ip = sockaddr[0]
                if ip == "127.0.0.1":
                    return True
            elif family == socket.AF_INET6:
                # IPv6 loopback address
                ip = sockaddr[0]
                if ip == "::1":
                    return True
        except (IndexError, TypeError):
            continue

    return False

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.
    """
    try:
        if find_paths is None:
            return []

        result = []
        for item in find_paths:
            # Treat any non‑string item as a literal fragment
            if not isinstance(item, str):
                path = str(item)
            else:
                path = item

            # If the string already contains a colon we assume it is a pattern and leave it unchanged
            if ':' in path:
                result.append(path)
            else:
                # Convert a plain fragment into a shell glob pattern
                # This pattern will match the fragment anywhere inside a path.
                result.append(f'sh:**/*{path}*/**')
        return result
    except Exception as exc:  # pragma: no cover
        raise ValueError(f"Failed to transform find paths: {exc}") from exc

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.
    """
    # Accept None as empty list
    if find_paths is None:
        return []
    # If a single string was supplied, treat it as a sequence of one item
    if isinstance(find_paths, str):
        find_paths = [find_paths]
    # Ensure we have an iterable; if not, raise a TypeError
    try:
        iterator = iter(find_paths)
    except Exception as exc:
        raise TypeError("find_paths must be an iterable of strings") from exc
    transformed = []
    for item in iterator:
        # Convert to string safely; skip items that cannot be converted
        try:
            fragment = str(item)
        except Exception:
            continue
        if fragment == "":
            # Skip empty fragments
            continue
        # Detect an existing pattern by the presence of a colon prefix
        if ":" in fragment:
            # Assume this is already a pattern and leave it unchanged
            transformed.append(fragment)
        else:
            # Wrap the fragment in a shell glob pattern
            transformed.append(f"sh:**/*{fragment}*/**")
    return transformed

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        if os.name != "nt":
            return False
        msystem = os.environ.get("MSYSTEM", "")
        if msystem.upper().startswith(("MINGW", "MSYS")):
            return True
        return False
    except Exception:
        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate inputs
    if config_filename is None:
        raise ValueError('config_filename must not be None')
    if not isinstance(config_filename, (str, os.PathLike)):
        raise TypeError('config_filename must be a string or path-like object')
    if not isinstance(rendered_config, str):
        raise TypeError('rendered_config must be a string containing YAML')
    if not isinstance(mode, int):
        raise TypeError('mode must be an integer file permission value')
    if not isinstance(overwrite, bool):
        raise TypeError('overwrite must be a boolean')

    target_path = os.fspath(config_filename)
    if os.path.exists(target_path) and not overwrite:
        raise FileExistsError(f'File {target_path} already exists and overwrite is False')

    # Ensure parent directories exist
    parent_dir = os.path.dirname(target_path)
    if parent_dir:
        try:
            os.makedirs(parent_dir, exist_ok=True)
        except Exception as exc:
            raise OSError(f'Could not create directories {parent_dir!r}: {exc}') from exc

    # Write the rendered configuration
    try:
        with open(target_path, 'w', encoding='utf-8') as fp:
            fp.write(rendered_config)
    except Exception as exc:
        raise IOError(f'Failed to write configuration to {target_path!r}: {exc}') from exc

    # Set file permissions
    try:
        os.chmod(target_path, mode)
    except Exception as exc:
        raise OSError(f'Failed to set permissions {oct(mode)} on {target_path!r}: {exc}') from exc
    return

def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    THis is useful to run a single ssh command and pass a one line script.

    :param script:
    :return:
    """
    # Handle None or non-string values
    if script is None:
        return ""
    if not isinstance(script, (str, bytes)):
        raise TypeError("script must be a string or bytes")
    # If bytes, decode to string
    if isinstance(script, bytes):
        try:
            script = script.decode('utf-8')
        except Exception as e:
            raise ValueError("failed to decode script bytes") from e

    try:
        # Strip outer whitespace and split into lines
        lines = [line.strip() for line in script.strip().splitlines()]
        # Filter out empty lines
        non_empty = [ln for ln in lines if ln]
        # Join using the provided separator
        return seperator.join(non_empty)
    except Exception as exc:
        # On any unexpected error return empty string or re-raise
        raise RuntimeError("Error converting script to single line") from exc

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Determine name and default from matcher
    if isinstance(matcher, dict):
        if 'name' not in matcher:
            raise ValueError('Matcher dict must contain a "name" key')
        name = matcher['name']
        default = matcher.get('default', None)
    elif isinstance(matcher, (list, tuple)):
        if len(matcher) == 0:
            raise ValueError('Matcher tuple/list must contain at least the variable name')
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    else:
        raise TypeError('Matcher must be a dict, list, or tuple')

