        if isinstance(match, dict):
            name = match.get('name') or match.get('var') or match.get('variable') or match.get('key')
            default = match.get('default')
        # Regex match object
        elif hasattr(match, 'groupdict'):
            gd = match.groupdict()
            name = gd.get('name') or gd.get('var') or gd.get('variable') or gd.get('key')
            default = gd.get('default')
        # Tuple or list
        elif isinstance(match, (list, tuple)):
            if len(match) == 0:
                raise ValueError('Empty matcher provided')
            name = match[0]
            if len(match) > 1:
                default = match[1]
        # Fallback: try positional groups
        else:
            try:
                name = match.group(1)
                # Try to get default if group 2 exists
                try:
                    default = match.group(2)
                except Exception:
                    default = None
            except Exception as e:
                raise TypeError(f'Unsupported matcher type: {type(match).__name__}') from e

        if name is None or name == '':
