def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    # Validate input
    if not isinstance(image_href, str) or not image_href.strip():
        raise ValueError("image_href must be a non-empty string")

    try:
        parsed = urllib.parse.urlparse(image_href.strip())
    except Exception as exc:
        raise ValueError(f"Invalid image href '{image_href}': {exc}") from exc

    # Ensure the scheme is either http or https
    if parsed.scheme not in {"http", "https"}:
        raise ValueError(
            f"Unsupported scheme '{parsed.scheme}' in image href '{image_href}'. "
            "Only 'http' and 'https' are allowed."
        )

    netloc = parsed.hostname or ""
    if not netloc:
        raise ValueError(f"Image href '{image_href}' does not contain a host part")

    use_ssl = parsed.scheme == "https"

    # Build the image_id from path, query, and fragment if present
    image_id = parsed.path
    if parsed.query:
        image_id += f"?{parsed.query}"
    if parsed.fragment:
        image_id += f"#{parsed.fragment}"

    return (image_id, netloc, use_ssl)

def remove_ending_os_sep(input_list):
    if not isinstance(input_list, list):
        raise TypeError("input_list must be a list")
    result = []
    for item in input_list:
        if not isinstance(item, str):
            raise TypeError("All items in input_list must be strings")
        if len(item) > 1 and item[-1] == os.sep:
            result.append(item[:-1])
