def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return a tuple: (dict of configuration filename to parsed configuration,
                     sequence of logging.LogRecord instances containing any parse errors).
    '''
    import logging
    import os
    import json
    import re
    results = {}
    error_records = []

    def _create_error_record(path, msg):
        return logging.LogRecord(
            name='config_loader',
            level=logging.ERROR,
            pathname=path,
            lineno=0,
            msg=msg,
            args=(),
            exc_info=None
        )

    def _resolve_env_vars(value):
        if isinstance(value, str) and resolve_env:
            # Replace ${VAR} with environment variable value
            def repl(match):
                return os.getenv(match.group(1), match.group(0))
            return re.sub(r'\${(\w+)}', repl, value)
        return value

    def _traverse_and_replace(obj):
        if isinstance(obj, dict):
            return {k: _traverse_and_replace(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_traverse_and_replace(v) for v in obj]
        else:
            return _resolve_env_vars(obj)

    # Ensure we have an iterable of filenames
    if config_filenames is None:
        config_filenames = []
    try:
        filenames_iter = iter(config_filenames)
    except TypeError:
        error_records.append(_create_error_record(
            "config_filenames", "config_filenames must be an iterable of file paths."
        ))
        return {}, error_records

    for raw_path in filenames_iter:
        if not isinstance(raw_path, str):
            record = _create_error_record(
                str(raw_path), f"Configuration filename must be a string, got {type(raw_path).__name__}."
            )
            error_records.append(record)
            continue

        path = os.path.expanduser(raw_path)
        try:
            with open(path, 'r', encoding='utf-8') as f:
                try:
                    # Try JSON first
                    parsed = json.load(f)
                except json.JSONDecodeError:
                    f.seek(0)
                    try:
                        import yaml
                        parsed = yaml.safe_load(f)
                    except Exception as ye:
                        # On yaml import errors or yaml parse errors
                        msg = f"Failed to parse configuration file '{path}': {ye}"
                        error_records.append(_create_error_record(path, msg))
                        continue
        except FileNotFoundError:
            error_records.append(_create_error_record(path, f"File not found: '{path}'"))
            continue
        except PermissionError:
            error_records.append(_create_error_record(path, f"Permission denied: '{path}'"))
            continue
        except Exception as e:
            error_records.append(_create_error_record(path, f"Error opening file '{path}': {e}"))
            continue

        # Validate that the parsed config is a dict
        if not isinstance(parsed, dict):
            error_records.append(_create_error_record(
                path, f"Configuration file '{path}' does not contain a JSON object (dict)."
            ))
            continue

        # Merge overrides if present
        if overrides and isinstance(overrides, dict):
            merged = {**parsed, **overrides}
        else:
            merged = parsed

        # Resolve environment variables recursively
        final_config = _traverse_and_replace(merged)

        results[path] = final_config

    return results, error_records

import logging
import os
import re
import json

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    if config_filenames is None:
        config_filenames = ()
    results = {}
    error_records = []
    logger_name = 'load_configurations'
    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as exc:
            err = logging.makeRecord(
                name=logger_name,
                level=logging.ERROR,
                fn=fname,
                lno=0,
                msg=f'Error opening file: {exc}',
                args=(),
                exc_info=None
            )
            error_records.append(err)
            continue

        # Resolve environment variables if requested
        if resolve_env:
            def repl(match):
                var = match.group(1)
                return os.getenv(var, '')
            content = re.sub(r'\${(\w+)}', repl, content)

        # Determine parser based on file extension
        ext = os.path.splitext(fname)[1].lower()
        try:
            if ext in {'.yaml', '.yml'}:
                try:
                    import yaml
                except ImportError:
                    raise ImportError("PyYAML is required for parsing YAML files.")
                config = yaml.safe_load(content)
            else:
                config = json.loads(content)
        except Exception as exc:
            err = logging.makeRecord(
                name=logger_name,
                level=logging.ERROR,
                fn=fname,
                lno=0,
                msg=f'Error parsing file: {exc}',
                args=(),
                exc_info=None
            )
            error_records.append(err)
            continue

        # Apply overrides if provided
        if overrides and isinstance(overrides, dict):
            if isinstance(config, dict):
                config.update(overrides)
            else:
                # If parsed config isn't a dict, we can't apply overrides
                err = logging.makeRecord(
                    name=logger_name,
                    level=logging.WARNING,
                    fn=fname,
                    lno=0,
                    msg='Overrides provided but config is not a dict.',
                    args=(),
                    exc_info=None
                )
                error_records.append(err)

        results[fname] = config

    return results, error_records

