            record = logging.LogRecord(
                name='load_config',
                level=logging.ERROR,
                fn=filename,
                lno=0,
                msg=msg,
                args=(),
                exc_info=(type(exc), exc, exc.__traceback__ if hasattr(exc, '__traceback__') else None)
            )
            error_records.append(record)

    return configs, error_records

