def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The function converts the input datetime to UTC (if timezone-aware)
    or assumes UTC (if naive). The resulting string is in ISO-8601
    format with UTC designator 'Z', e.g. '2023-07-25T14:30:00Z'.
    Strings can also be accepted if they are ISO-8601 compliant.
    """
    import datetime
    if dt is None:
        return ''
    # If we receive a datetime instance
    if isinstance(dt, datetime.datetime):
        # Normalize to UTC
        if dt.tzinfo is not None:
            utc_dt = dt.astimezone(datetime.timezone.utc)
        else:
            utc_dt = dt
        return utc_dt.strftime('%Y-%m-%dT%H:%M:%SZ')
    # If we receive a string, try to parse it
    if isinstance(dt, str):
        try:
            # Handle 'Z' as UTC
            iso_str = dt.replace('Z', '+00:00')
            parsed = datetime.datetime.fromisoformat(iso_str)
            if parsed.tzinfo is not None:
                parsed = parsed.astimezone(datetime.timezone.utc)
            return parsed.strftime('%Y-%m-%dT%H:%M:%SZ')
        except Exception as exc:
            raise TypeError(f"Unable to parse datetime string '{dt}': {exc}") from exc
    raise TypeError(f"Unsupported type for dt: {type(dt)}")

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.

    This function accepts a :class:`datetime.datetime` instance and returns
    a string representation suitable for storage or transmission to D* nodes.
    If the datetime is naive it is treated as UTC and a trailing ``Z`` is
    appended.  If it is timezone‑aware the offset is preserved.  The function
    validates its input and raises a *ValueError* for unsupported values.
    """
    # Ensure we received a datetime-like object
    if dt is None:
        raise ValueError("dt must not be None")
    if not hasattr(dt, "isoformat") or not hasattr(dt, "tzinfo"):
        raise TypeError("dt must be a datetime.datetime instance")

    try:
        if dt.tzinfo is None:
            # Treat naive datetimes as UTC
            return dt.isoformat(timespec="seconds") + "Z"
        # Time‑zone aware datetimes are formatted with the offset included
        return dt.isoformat(timespec="seconds")
    except Exception as exc:
        raise ValueError(f"Unable to format datetime: {exc}") from exc

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    if not isinstance(text, str):
        raise TypeError("text must be a string")

    # Add target and rel attributes to existing <a> tags if missing
    def _add_attrs(match: re.Match) -> str:
        attrs = match.group(1) or ""
        # Ensure there's a leading space for consistency if attrs exist
        if attrs and not attrs.startswith(" "):
            attrs = " " + attrs
        if 'target=' not in attrs:
            attrs += ' target="_blank"'
        if 'rel=' not in attrs:
            attrs += ' rel="noopener noreferrer"'
        return f"<a{attrs}>"

    text = re.sub(r'<a\b([^>]*)>', _add_attrs, text)

    # Helper to linkify plain URLs
    url_pattern = re.compile(r'\b((?:https?://|www\.)[^\s<]+)')
    def _linkify_segment(segment: str) -> str:
        def repl(m: re.Match) -> str:
            url = m.group(1)
            href = url if url.startswith(("http://", "https://")) else f"http://{url}"
            return f'<a href="{href}" target="_blank" rel="noopener noreferrer">{url}</a>'
        return url_pattern.sub(repl, segment)

    # Split text at <a>...</a> tags to avoid re-linkifying inside them
    parts = re.split(r'(<a\b[^>]*>.*?</a>)', text, flags=re.DOTALL)
    for i, part in enumerate(parts):
        if not part.startswith("<a "):
            parts[i] = _linkify_segment(part)

    return "".join(parts)

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        from urllib.request import Request, urlopen
        from urllib.error import URLError, HTTPError
    except Exception:
        # urllib is part of the standard library; failure here means
        # the environment is not standard. Return None.
        return None

    # Prepare a HEAD request; urllib allows setting the method (Python 3.3+)
    try:
        req = Request(url, method="HEAD")
    except TypeError:
        # For older Python versions that do not support the `method` argument,
        # we add the method via a custom header and set the data to None.
        # This makes urllib issue a HEAD request.
        req = Request(url)
        req.get_method = lambda: "HEAD"

    try:
        with urlopen(req, timeout=10) as response:
            # urllib.response info returns a Message object
            content_type = response.info().get("Content-Type")
            if content_type:
                return content_type.strip()
            return None
    except (HTTPError, URLError, ValueError, Exception):
        # HTTPError covers non-200 status codes
        return None

