def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    def _parse_json(doc: str) -> Dict:
        try:
            data = json.loads(doc)
        except json.JSONDecodeError as e:
            raise ValueError(f"JSON parsing error: {e}") from e

        # Ensure 'subject' key exists
        if "subject" not in data:
            raise ValueError("Missing 'subject' in webfinger JSON")
        # Normalize lists
        aliases = list(data.get("aliases", []))
        links = list(data.get("links", []))
        properties = dict(data.get("properties", {}))
        return {
            "subject": data["subject"],
            "aliases": aliases,
            "properties": properties,
            "links": links,
        }

    def _parse_xrd(doc: str) -> Dict:
        try:
            root = ET.fromstring(doc)
        except ET.ParseError as e:
            raise ValueError(f"XML parsing error: {e}") from e

        # Namespace handling
        ns = {}
        if root.tag.startswith("{"):
            uri, _, _ = root.tag[1:].partition("}")
            ns["xrd"] = uri
        else:
            ns["xrd"] = ""

        def _s(tag):
            return f"{{{ns['xrd']}}}{tag}" if ns["xrd"] else tag

        subject_elem = root.find(_s("Subject"))
        if subject_elem is None or subject_elem.text is None:
            raise ValueError("Missing 'Subject' element in XRD")
        subject = subject_elem.text.strip()

        aliases = [a.text.strip() for a in root.findall(_s("Alias")) if a.text]

        properties: Dict[str, str] = {}
        for prop in root.findall(_s("Property")):
            prop_type = prop.attrib.get("type")
            prop_value = prop.text.strip() if prop.text else ""
            if prop_type:
                properties[prop_type] = prop_value
            else:
                # If no type, use element text as key?  use index
                properties[prop_value] = ""

        links = []
        for link in root.findall(_s("Link")):
            rel = link.attrib.get("rel")
            href = link.attrib.get("href")
            typ = link.attrib.get("type")
            if rel and href:
                link_dict = {"rel": rel, "href": href}
                if typ:
                    link_dict["type"] = typ
                links.append(link_dict)

        return {
            "subject": subject,
            "aliases": aliases,
            "properties": properties,
            "links": links,
        }

    # First try JSON, if that fails, try XRD
    try:
        return _parse_json(document)
    except ValueError:
        try:
            return _parse_xrd(document)
        except ValueError as e:
            raise ValueError("Unable to parse Diaspora webfinger") from e

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try JSON first
    try:
        json_lib = __import__("json")
        data = json_lib.loads(document)
        # Normalise keys to lowercase
        return {
            "subject": data.get("Subject") or data.get("subject"),
            "aliases": data.get("Aliases") or data.get("aliases") or [],
            "links": [
                {"rel": l.get("rel"), "type": l.get("type"), "href": l.get("href")}
                for l in data.get("Links", [])
                if l.get("href")
