        data = json.loads(document)
        if isinstance(data, dict):
            subject = data.get('subject')
            aliases = data.get('aliases') or []
            links = data.get('links') or []
            # Ensure types
            if not isinstance(aliases, list):
                aliases = [aliases]
            if not isinstance(links, list):
                links = [links]
            return {
                'subject': subject,
                'aliases': aliases,
                'links': links
            }
    except Exception:
        # Fall through to XRD parsing
        pass
    # Try XRD parsing
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
        def _localname(tag):
            return tag.split('}')[-1] if '}' in tag else tag
        subject = None
        aliases = []
        links = []
        for elem in root.iter():
            local = _localname(elem.tag)
            if local == 'Subject':
                subject = elem.text.strip() if elem.text else None
            elif local == 'Alias':
                if elem.text:
                    aliases.append(elem.text.strip())
            elif local == 'Link':
                attrs = elem.attrib
                link = {}
                for key in ('rel', 'type', 'href', 'title'):
                    if key in attrs:
                        link[key] = attrs[key]
                if link:
                    links.append(link)
        return {
            'subject': subject,
            'aliases': aliases,
            'links': links
        }
    except Exception:
        pass
    raise ValueError("Unable to parse Diaspora webfinger document")

