def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    # Coerce input to a list of directory strings
    try:
        if settings_dirs is None:
            dir_list = []
        elif isinstance(settings_dirs, str):
            dir_list = [settings_dirs]
        else:
            dir_list = [d for d in settings_dirs if isinstance(d, str)]
    except Exception:
        dir_list = []

    _os = __import__('os')
    _fnmatch = __import__('fnmatch')
    result = []

    for d in dir_list:
        if not d:
            continue
        try:
            if not _os.path.isdir(d):
                continue
        except Exception:
            continue
        try:
            for root, _, files in _os.walk(d, topdown=True):
                for f in files:
                    full_path = _os.path.join(root, f)
                    if spec_option is None or spec_option == "":
                        result.append(full_path)
                    else:
                        try:
                            if _fnmatch.fnmatch(f, spec_option):
                                result.append(full_path)
                        except Exception:
                            continue
        except Exception:
            continue
    return result

def list_of_file_names(settings_dirs, spec_option):
    """
    Create a new IniType complex type
    """
    # Helper imports via runtime import
    os = __import__('os')
    fnmatch = __import__('fnmatch').fnmatch

    # Validate inputs
    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    elif isinstance(settings_dirs, (list, tuple)):
        dirs = list(settings_dirs)
    else:
        raise TypeError("settings_dirs must be a string or an iterable of strings")

    if not isinstance(spec_option, str):
        raise TypeError("spec_option must be a string")

    # Prepare spec for matching
    spec_option = spec_option.strip()
    wild_card = '*' in spec_option or '?' in spec_option
    if not wild_card:
        # Ensure leading dot for extension matching
        if spec_option and not spec_option.startswith('.'):
            spec_option = '.' + spec_option
        spec_option = spec_option.lower()

    matched_files = []

    for basedir in dirs:
        try:
            for entry in os.listdir(basedir):
                full_path = os.path.join(basedir, entry)
                if not os.path.isfile(full_path):
                    continue

                if not spec_option:
                    matched = True
                elif wild_card:
                    matched = fnmatch(entry, spec_option)
                else:
                    matched = entry.lower().endswith(spec_option)

                if matched:
                    matched_files.append(full_path)
        except Exception:
            # Skip directories that cannot be accessed
            continue

    # Remove duplicates and sort for consistency
    return sorted(set(matched_files))

