def _include_groups(self, parser_dict):
        """
        Resolves the include dict directive in the spec files.
        The directive may specify additional spec fragments that should be
        merged into the current spec dictionary.  Each entry in the
        ``include`` mapping can be either

          * a path to another spec file (JSON or YAML), or
          * a nested dictionary that should be merged directly.

        The method returns a new dictionary that contains the merged data.
        The original ``parser_dict`` is not modified.
        """
        import os
        # Attempt to import yaml if available.  If not available, raise
        # an informative error when a file include is encountered.
        try:
            import yaml
        except Exception:
            yaml = None

        if not isinstance(parser_dict, dict):
            raise ValueError("parser_dict must be a dictionary")

        # Work on a shallow copy to avoid mutating the original
        merged = dict(parser_dict)

        include = merged.get("include")
        if include is None:
            return merged  # nothing to include

        if not isinstance(include, dict):
            raise ValueError("'include' must be a dictionary in spec")

        # Clean up the directive after processing
        merged.pop("include")

        for key, val in include.items():
            # If the value is a string, interpret it as a file path
            if isinstance(val, str):
                # Resolve relative paths relative to the current working dir
                file_path = os.path.abspath(val)
                if not os.path.isfile(file_path):
                    raise FileNotFoundError(f"Included spec file not found: {file_path}")

                # Load the file content
                with open(file_path, 'r', encoding='utf-8') as f:
                    try:
                        if yaml and (file_path.lower().endswith(('.yml', '.yaml'))):
                            content = yaml.safe_load(f)
                        else:
                            import json
                            content = json.load(f)
                    except Exception as e:
                        raise ValueError(f"Failed to parse included spec file '{file_path}': {e}")

            # If the value is a dictionary, use it directly
            elif isinstance(val, dict):
                content = val
            else:
                raise ValueError(f"Unsupported include entry type for key '{key}': {type(val).__name__}")

            if not isinstance(content, dict):
                raise ValueError(f"Included content for '{key}' must be a dictionary")

            # Deep merge the included content into the result
            def _deep_merge(d1, d2):
                for k, v in d2.items():
                    if (
                        k in d1
                        and isinstance(d1[k], dict)
                        and isinstance(v, dict)
                    ):
                        _deep_merge(d1[k], v)
                    else:
                        d1[k] = v

            _deep_merge(merged, content)

        return merged

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        # Extract the specification dictionary
        spec = getattr(self, "spec", {})
        if not isinstance(spec, dict):
            return defaults

        # Gather default values defined in the spec
        for arg_name, arg_entry in spec.items():
            # If the spec entry is a dict, look for a 'default' key
            if isinstance(arg_entry, dict):
                default_val = arg_entry.get("default")
            else:
                # If the entry is not a dict, treat the entry itself as the default
                default_val = arg_entry
            if default_val is not None:
                defaults[arg_name] = default_val

        # Merge with any additional sources that may be defined on the instance
        # (e.g., configuration files, environment overrides, etc.)
        if hasattr(self, "other_sources"):
            for key, val in getattr(self, "other_sources", {}).items():
                defaults.setdefault(key, val)
    except Exception:
        # If any unexpected issue occurs, fall back to an empty defaults dict
        defaults = {}
    return defaults

