    argument, a `default` or `defaultValue` key (if present) is taken,
    otherwise the spec entry itself is used as the default.  The method
    then looks for environment variable overrides using an optional
    `envprefix` attribute; any matching environment variable is
    parsed and cast to the type of the spec default.  Finally, if the
    instance has an `overrides` mapping, the values from this mapping
    replace any previous defaults.  Errors during parsing are swallowed
    and the raw environment string is used instead.

    Returns:
        dict: Mapping of argument names to resolved default values.

    Raises:
        None: All steps are wrapped in safe exception handling and
              fall through to sensible defaults where possible.
    """
    # We'll do imports locally to obey the no-import-statement rule.
    try:
        import os
    except Exception:
        # If the import fails for some reason, we cannot read env vars.
        os = None

    defaults = {}

    # Pull defaults from spec.
    spec = getattr(self, "spec", {})
    if isinstance(spec, dict):
        for arg, cfg in spec.items():
            # If the config is a dict, look for 'default' keys.
            if isinstance(cfg, dict):
                # Prefer explicit 'default', otherwise fallback to 'defaultValue'.
                if "default" in cfg:
                    defaults[arg] = cfg["default"]
                elif "defaultValue" in cfg:
                    defaults[arg] = cfg["defaultValue"]
            else:
                # If the config is not a dict, treat it as the default.
                defaults[arg] = cfg

    # Apply overrides from environment variables.
    envprefix = getattr(self, "envprefix", None)
    if envprefix and os and isinstance(envprefix, str):
        for key in list(defaults):
            env_key = f"{envprefix}_{key}".upper()
            env_val = os.getenv(env_key)
            if env_val is not None:
                # Helper to cast env value to the original type
                def _cast(val, default):
                    try:
                        if isinstance(default, bool):
                            if val.lower() in ("1", "true", "yes", "on"):
                                return True
                            if val.lower() in ("0", "false", "no", "off"):
                                return False
                        if isinstance(default, int):
                            return int(val)
                        if isinstance(default, float):
                            return float(val)
                        # For lists or other complex types, we leave as string.
                    except Exception:
                        return val
                    return val
                defaults[key] = _cast(env_val, defaults[key])

    # Apply any explicit overrides on the instance.
    overrides = getattr(self, "overrides", {})
    if isinstance(overrides, dict):
        defaults.update(overrides)

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Ensure the instance has a 'spec' attribute that is a dictionary
    try:
        spec = getattr(self, 'spec')
    except AttributeError:
        raise AttributeError("The instance must have a 'spec' attribute")
    if not isinstance(spec, dict):
        raise TypeError("'spec' must be a dictionary")

    defaults = {}
    # Retrieve the arguments definition; it can be a list or a dict
    arguments = spec.get('arguments', [])
    if isinstance(arguments, dict):
        # convert dict of name -> arg_spec to list of (name, arg_spec)
        arguments = list(arguments.items())
    if not isinstance(arguments, (list, tuple)):
        raise TypeError("'spec['arguments']' must be a list or dict")

    for entry in arguments:
        # Allow two styles:
        # 1. entry is a dict with optional 'name' field
        # 2. entry is a tuple/list of (name, spec_dict)
        name = None
        arg_spec = None

        if isinstance(entry, dict):
            # Prefer explicit 'name' key
            name = entry.get('name')
            # In some formats the key itself might be the name
            if not name:
                name = entry.get('key') or entry.get('id')
            arg_spec = entry
        elif isinstance(entry, (list, tuple)) and len(entry) == 2:
            name, arg_spec = entry
        else:
            # Unsupported format; skip
            continue

        if not isinstance(name, str):
            continue

        # Attempt to get a default value from the spec
        default_val = None
        if isinstance(arg_spec, dict):
            default_val = arg_spec.get('default')

        # If no default in spec, try other sources
        if default_val is None:
            if hasattr(self, 'options') and isinstance(self.options, dict) and name in self.options:
                default_val = self.options[name]
            elif hasattr(self, 'config') and isinstance(self.config, dict) and name in self.config:
                default_val = self.config[name]
            else:
                default_val = None

        defaults[name] = default_val

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Retrieve the specification dictionary defined on this instance.
    spec = getattr(self, "spec", None)
    if spec is None:
        raise AttributeError("`spec` attribute is missing or None.")
    if not isinstance(spec, dict):
        raise TypeError("`spec` attribute must be a dictionary.")

    defaults = {}
    for arg_name, arg_spec in spec.items():
        # Skip non-dict entries in the spec to be robust.
        if not isinstance(arg_spec, dict):
            continue

        # Prefer an explicit 'default' key.
        if "default" in arg_spec:
            defaults[arg_name] = arg_spec["default"]
            continue

        # Optionally resolve a default value from another source specified by 'defaultFrom'.
        if "defaultFrom" in arg_spec:
            source_expr = arg_spec["defaultFrom"]
            try:
                # Allow expressions that reference self attributes, globals, or locals.
                # Guard against malicious code by limiting globals.
                defaults[arg_name] = eval(source_expr, {"self": self}, {})
            except Exception:
                # If evaluation fails, fall back to None.
                defaults[arg_name] = None
            continue

        # If no explicit default or defaultFrom, default to None.
        defaults[arg_name] = None

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # First try to fetch defaults from the spec object if it exists
    spec = getattr(self, "spec", None)
    if not spec:
        return defaults
    try:
        # If spec is a mapping, use its values directly
        if isinstance(spec, dict):
            defaults.update(spec)
        # If spec has a 'defaults' attribute, use it
        elif hasattr(spec, "defaults"):
            spec_defaults = getattr(spec, "defaults", {})
            if isinstance(spec_defaults, dict):
                defaults.update(spec_defaults)
    except Exception:
        # If anything goes wrong, silently ignore and return what we have
        pass
    return defaults.copy()

