def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    import sys

    # Basic type validation
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Retrieve deprecated arguments mapping
    # Supports either an iterable of old names or a mapping old->new
    deprecated = getattr(self, "deprecated_args", None)
    if not deprecated:
        return  # nothing to check

    # Normalize to list of tuples (old_name, new_name)
    if isinstance(deprecated, dict):
        deprecated_items = list(deprecated.items())
    else:
        try:
            deprecated_items = [(arg, None) for arg in deprecated]
        except TypeError:
            raise TypeError(
                "deprecated_args must be a dict or an iterable of argument names"
            )

    # Helper to format warning message
    def _format_msg(arg, new, source):
        msg = f"Argument '{arg}' from {source} is deprecated."
        if new:
            msg += f" Use '{new}' instead."
        return msg

    # Check CLI arguments
    for old_arg, new_arg in deprecated_items:
        if old_arg in cli_args:
            sys.stderr.write(_format_msg(old_arg, new_arg, "CLI") + "\n")

    # Check answer file arguments
    for old_arg, new_arg in deprecated_items:
        if old_arg in answer_file_args:
            sys.stderr.write(_format_msg(old_arg, new_arg, "answer file") + "\n")

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # A mapping of deprecated argument names to their deprecation message, if any.
    deprecated_map = getattr(self, "deprecated_arguments", {})

    def _check(source, args):
        for key in args:
            if key in deprecated_map:
                # Print a deprecation warning.  Preserve the source
                # (e.g. "command line" or "answer file") for clarity.
                msg = deprecated_map[key]
                if not msg:
                    msg = "This argument has been removed and is no longer supported."
                print(f"WARNING: The argument '{key}' supplied via {source} is "
                      f"deprecated. {msg}")

    if cli_args is not None:
        if not isinstance(cli_args, dict):
            raise TypeError("cli_args must be a dictionary")
        _check("command line", cli_args)

    if answer_file_args is not None:
        if not isinstance(answer_file_args, dict):
            raise TypeError("answer_file_args must be a dictionary")
        _check("answer file", answer_file_args)

    # No return value; side‑effects are the printed warnings."""

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    # Attempt to retrieve the mapping of command names to option specs
    try:
        command_options = self._command_options
    except AttributeError:
        raise AttributeError(
            "The object does not have a '_command_options' attribute "
            "to retrieve option specifications."
        )

    # Retrieve options for the requested command
    try:
        options = command_options[command_name]
    except KeyError:
        raise ValueError(f"Unknown command: {command_name!r}")

    # Ensure a list is returned, converting if necessary
    if isinstance(options, list):
        return options
    if hasattr(options, "__iter__") and not isinstance(options, str):
        return list(options)

    # If something unexpected is returned, wrap it in a list
    return [options]

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # validate command_name
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    # Check that the parser instance is available
    try:
        parser = self.parser
    except AttributeError:
        raise AttributeError("The object has no 'parser' attribute")

    # Helper to get non‑subparser actions from a parser
    def _direct_actions(p):
        return [a for a in getattr(p, "_actions", []) if not isinstance(a, getattr(argparse, "_SubParsersAction", (type(None),)))]  # type: ignore

    # If main command, return top‑level options
    if command_name.lower() == "main":
        return _direct_actions(parser)

    # Find the SubParsersAction container
    subparsers_action = None
    for action in getattr(parser, "_actions", []):
        if isinstance(action, getattr(argparse, "_SubParsersAction", (type(None),))):  # type: ignore
            subparsers_action = action
            break

    if subparsers_action is None:
        raise ValueError(f"No subparsers found in the parser for command '{command_name}'")

    # Search for the requested subparser
    for sub_action in getattr(subparsers_action, "_actions", []):
        # In argparse 3.x, the subparser action has .name attribute
        if getattr(sub_action, "name", None) == command_name:
            return _direct_actions(sub_action.parser)

    raise ValueError(f"Command '{command_name}' not found in the parser")

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")
    try:
        # Attempt to retrieve the command registry attribute
        commands = getattr(self, "commands", {})
        if not isinstance(commands, dict):
            commands = getattr(self, "_commands", {})
        if command_name not in commands:
            raise KeyError
        cmd_obj = commands[command_name]
        # Retrieve the options mapping from the command object
        options = getattr(cmd_obj, "options", {})
        if not isinstance(options, dict):
            options = {}
        if argument_name not in options:
            raise KeyError
        return options[argument_name]
    except KeyError:
        raise KeyError(
            f"Option '{argument_name}' not found for command '{command_name}'."
        )
    except Exception as exc:
        raise RuntimeError(
            f"Error retrieving option spec for command '{command_name}' and argument '{argument_name}'."
        ) from exc

def get_option_spec(self, command_name, argument_name):
