        raise ValueError(f"Command '{command_name}' does not exist.") from exc

    # Attempt to retrieve the option specification within the command
    try:
        option_spec = command.options[argument_name]
    except Exception as exc:
        raise ValueError(f"Option '{argument_name}' not found in command '{command_name}'.") from exc

    return option_spec

