def get_option_spec(self, command_name, argument_name):
    """
    Retrieves the specification for a given option name within a specified command.
    The method first validates the input types and then attempts to locate the
    option specification within the instance's command registry. If the command
    or option does not exist, ``None`` is returned. Exceptions during the lookup
    are caught and re-raised as ``ValueError`` with a descriptive message.
    """
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")

    try:
        # The registry is expected to be a dict stored on the instance
        registry = getattr(self, "commands", {})
        if not isinstance(registry, dict):
            raise TypeError("commands attribute is not a mapping")

        cmd_spec = registry.get(command_name)
        if cmd_spec is None:
            return None

        # If the command spec is a dictionary, look for an 'options' mapping
        if isinstance(cmd_spec, dict):
            options = cmd_spec.get("options", {})
            if isinstance(options, dict):
                # Direct lookup by option name
                return options.get(argument_name)
            # Support list of option spec dicts
            if isinstance(options, list):
                for opt in options:
                    if isinstance(opt, dict) and opt.get("name") == argument_name:
                        return opt
            return None

        # If the command spec is an object, inspect its attributes
        options = getattr(cmd_spec, "options", None)
        if options is None:
            return None

        if isinstance(options, dict):
            return options.get(argument_name)

        if isinstance(options, list):
            for opt in options:
                name = getattr(opt, "name", None)
                if name == argument_name:
                    return opt

        # Fallback: try to call a method on the object
        if hasattr(cmd_spec, "get_option_spec"):
            return getattr(cmd_spec, "get_option_spec")(argument_name)

        return None

    except Exception as exc:
        raise ValueError(
            f"Error retrieving option spec for command '{command_name}' and "
            f"argument '{argument_name}': {exc}"
        ) from exc

def get_silent_args(self, args):
    """
    List of silenced argument names.

    :param args: The received arguments. Can be a dict, or an object with a `_get_kwargs`
                 method (e.g., argparse.Namespace).
    :return: List of argument names whose values are considered "silent"
             (i.e., None). If the input type cannot be processed, an empty list
             is returned.
    """
    try:
        if isinstance(args, dict):
            silent = [k for k, v in args.items() if v is None]
        elif hasattr(args, "_get_kwargs"):
            silent = [k for k, v in args._get_kwargs() if v is None]
        else:
            silent = []
    except Exception:
        silent = []
    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a dictionary
    if not isinstance(args, dict):
        raise TypeError(f"'args' must be a dictionary, got {type(args).__name__}")
    # Get the list of required arguments from the instance, if any
    required = getattr(self, 'requires', None)
    if not required:
        # No required arguments specified; nothing to validate
        return True
    # Iterate over required arguments to confirm presence and non‑None value
    for name in required:
        if name not in args or args[name] is None:
            raise ValueError(f"Missing required argument: '{name}'")
    # All required arguments present
    return True

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    condition_args = []
    # Basic sanity checks
    if not isinstance(command_name, str):
        return condition_args
    if not isinstance(options_spec, (list, tuple)):
        return condition_args

    for opt in options_spec:
        try:
            if not isinstance(opt, dict):
                continue
            name = opt.get("name")
            if not name:
                continue
            req_when = opt.get("required_when")
            if req_when is None:
                continue

            # Handle different possible shapes of required_when
            if isinstance(req_when, list):
                # A list of command names
                if command_name in req_when:
                    condition_args.append(name)
            elif isinstance(req_when, dict):
                # Mapping command name -> condition
                if command_name in req_when:
                    cond = req_when[command_name]
                    if isinstance(cond, bool):
                        if cond:
                            condition_args.append(name)
                    elif isinstance(cond, str):
                        # Assume the string is the name of an argument that must be present
                        if cond in args:
                            condition_args.append(name)
                    elif callable(cond):
                        try:
                            if cond(args):
                                condition_args.append(name)
                        except Exception:
                            pass
            elif isinstance(req_when, bool):
                if req_when:
                    condition_args.append(name)
            elif isinstance(req_when, str):
                # Simple requirement that a specific arg name must be present
                if req_when in args:
                    condition_args.append(name)
        except Exception:
            # Skip malformed option entries
            continue

    # Preserve order but remove duplicates
    seen = set()
    unique_args = []
    for a in condition_args:
        if a not in seen:
            seen.add(a)
            unique_args.append(a)

    return unique_args

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        required_args = []

        # If args is not a dict we cannot use it to check conditions.
        args_dict = args if isinstance(args, dict) else {}

        for opt in options_spec:
            try:
                # get the option name (allow dicts or objects)
                if isinstance(opt, dict):
                    opt_name = opt.get("name") or opt.get("dest")
                    opt_condition = opt.get("required_when")
                else:
                    opt_name = getattr(opt, "name", None) or getattr(opt, "dest", None)
                    opt_condition = getattr(opt, "required_when", None)

                if not opt_name or opt_condition is None:
                    continue

                # Determine if the condition matches the supplied args
                match = False

                # Condition can be a dict, list of dicts, callable, or any truthy value
                if isinstance(opt_condition, dict):
                    match = all(
                        args_dict.get(k) == v for k, v in opt_condition.items()
                    )
                elif isinstance(opt_condition, list):
                    for cond in opt_condition:
                        if isinstance(cond, dict):
                            if all(
                                args_dict.get(k) == v for k, v in cond.items()
                            ):
                                match = True
                                break
                elif callable(opt_condition):
                    try:
                        match = bool(opt_condition(args_dict))
                    except Exception:
                        match = False
                else:
                    match = bool(opt_condition)

                if match:
                    required_args.append(opt_name)

            except Exception:
                # Skip any problematic option spec silently
                continue

        return required_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
