        try:
            cond = opt.get('required_when') if isinstance(opt, dict) else getattr(opt, 'required_when', None)
        except Exception:
            cond = None

        if not cond:
            continue

        # Evaluate the condition
        matched = False
        # Try callable
        if callable(cond):
            try:
                matched = bool(cond(arg_map))
            except Exception:
                matched = False
        # Try list/tuple of conditions (logical OR)
        elif isinstance(cond, (list, tuple)):
            for subcond in cond:
                if callable(subcond):
