                        if subcond(arg_map):
                            matched = True
                            break
                    except Exception:
                        continue
                else:
                    try:
                        if eval(subcond, {}, arg_map):
                            matched = True
                            break
                    except Exception:
                        continue
        # Try string expression
        elif isinstance(cond, str):
            try:
                matched = bool(eval(cond, {}, arg_map))
            except Exception:
                matched = False
        # Treat other types as boolean
        else:
            try:
                matched = bool(cond)
            except Exception:
                matched = False

        if matched:
            cond_required.append(opt_name)

    return cond_required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Ensure args is a dictionary
    if not isinstance(args, dict):
        raise TypeError("`args` must be a dictionary mapping argument names to values")

    # Iterate over each provided argument
    for arg_name, arg_value in args.items():
        # Attempt to obtain the maximum allowed length for this argument
        max_len = None

        # Common patterns: a mapping of argument definitions
        if hasattr(self, "arg_defs") and isinstance(self.arg_defs, dict):
            definition = self.arg_defs.get(arg_name)
            if definition:
                if isinstance(definition, dict):
                    max_len = definition.get("max_length")
                else:
                    max_len = getattr(definition, "max_length", None)

        # Fallback: a separate mapping of max lengths
        if max_len is None and hasattr(self, "max_lengths") and isinstance(self.max_lengths, dict):
            max_len = self.max_lengths.get(arg_name)

        # If no length specification exists, skip validation for this argument
        if max_len is None:
            continue

        # Ensure the max length is a non‑negative integer; otherwise ignore
        if not isinstance(max_len, int) or max_len < 0:
            continue

        # Skip validation if the argument value is None or does not support len()
        if arg_value is None:
            continue
        try:
            value_len = len(arg_value)
        except Exception:
            continue

        if value_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' exceeds maximum length {max_len} "
                f"(got {value_len} characters)."
            )

    # All provided arguments passed length checks
    return True

