def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        Parameters
        ----------
        args : dict
            The received arguments.

        Raises
        ------
        TypeError
            If ``args`` is not a mapping.
        ValueError
            If any provided choice is not among the allowed values.
        """
        if not isinstance(args, Mapping):
            raise TypeError(f"Expected `args` to be a mapping, got {type(args).__name__}")

        # The mapping of argument names to a list or set of valid choices.
        # Assume it is defined on the instance; provide a safe fallback.
        available_choices = getattr(self, "choices", {})
        if not isinstance(available_choices, Mapping):
            raise TypeError(f"Expected `self.choices` to be a mapping, got {type(available_choices).__name__}")

        for key, value in args.items():
            # Skip arguments that have no predefined choices
            if key not in available_choices:
                continue

            allowed = available_choices[key]
            if allowed is None:
                continue

            # Normalize allowed to a set for efficient lookup
            if not isinstance(allowed, set):
                allowed_set = set(allowed)
            else:
                allowed_set = allowed

            # Handle list-like values (repeatable arguments)
            if isinstance(value, (list, tuple)):
                for elem in value:
                    if elem is None:
                        continue
                    if elem not in allowed_set:
                        raise ValueError(
                            f"Invalid value for argument '{key}': {elem!r} "
                            f"not in allowed choices {allowed_set}"
                        )
            else:
                if value is None:
                    continue
                if value not in allowed_set:
                    raise ValueError(
                        f"Invalid value for argument '{key}': {value!r} "
                        f"not in allowed choices {allowed_set}"
                    )

