def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments. Can be a dictionary or an iterable of values.
        :raises ValueError: If any argument is outside the allowed range.
        :raises TypeError: If args is not a dict or iterable, or if values cannot be compared.
        """
        # Determine the bounds from the instance attributes. Fall back to None if not set.
        min_val = getattr(self, "min_val", None)
        if min_val is None:
            min_val = getattr(self, "min", None)

        max_val = getattr(self, "max_val", None)
        if max_val is None:
            max_val = getattr(self, "max", None)

        if min_val is None and max_val is None:
            # No bounds defined; nothing to validate
            return

        if args is None:
            raise ValueError("No arguments provided for validation.")

        # Helper to validate a single value against bounds
        def _check_value(name, value):
            try:
                if min_val is not None and value < min_val:
                    raise ValueError(f"Argument '{name}'={value} below minimum {min_val}")
                if max_val is not None and value > max_val:
                    raise ValueError(f"Argument '{name}'={value} above maximum {max_val}")
            except TypeError as exc:
                raise TypeError(f"Cannot compare argument '{name}'={value} with bounds: {exc}")

        # If args is a mapping: validate each key/value
        if isinstance(args, dict):
            for key, val in args.items():
                _check_value(key, val)
        # If args is an iterable of values (list, tuple, set, etc.)
        elif hasattr(args, "__iter__") and not isinstance(args, str):
            for idx, val in enumerate(args):
                _check_value(f"arg[{idx}]", val)
        else:
            raise TypeError("Arguments must be a dictionary or an iterable of values.")

