def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Normalise input to iterable of (key, value) pairs
    items = []
    try:
        if args is None:
            return control_args, nested_args

        # If args is already a dict, use its items
        if isinstance(args, dict):
            items = list(args.items())
        else:
            # Assume iterable of strings or tuples
            for entry in args:
                if isinstance(entry, tuple) and len(entry) == 2:
                    key, val = entry
                elif isinstance(entry, str):
                    if "=" in entry:
                        key, val = entry.split("=", 1)
                    else:
                        key, val = entry, None
                else:
                    # Unrecognised format; skip
                    continue
                items.append((key, val))
    except Exception:
        # If any unexpected error occurs, treat all as nested args
        for entry in args:
            if isinstance(entry, str):
                nested_args[entry] = None
        return control_args, nested_args

    # Process each key/value pair
    for key, val in items:
        try:
            # Detect control arguments
            if isinstance(key, str):
                lower_key = key.lower()
                if lower_key.startswith("control_") or lower_key == "control":
                    clean_key = key[len("control_") :] if lower_key.startswith("control_") else key
                    control_args[clean_key] = val if val is not None else True
                    continue
                if lower_key.startswith("custom_") or lower_key == "custom":
                    clean_key = key[len("custom_") :] if lower_key.startswith("custom_") else key
                    # Custom args are treated as nested but may be flagged specially
                    nested_args[clean_key] = val if val is not None else True
                    continue
            # Default handling: nested arguments
            if key is not None:
                nested_args[key] = val if val is not None else True
        except Exception:
            # If any specific entry fails, skip it to avoid breaking the whole process
            continue

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        if args is None:
            return {}, {}

        control_args = {}
        nested_args = {}

        # Helper to process a key/value pair
        def _add_pair(k, v):
            if not isinstance(k, str):
                return
            k = k.strip()
            v = None if v is None else v.strip() if isinstance(v, str) else v
            if k.startswith("control_"):
                # strip the prefix and store
                control_args[k[len("control_"):]] = v
            elif k.startswith("custom_"):
                # treat as nested but with prefix stripped
                nested_args[k[len("custom_"):]] = v
            else:
                # normal nested argument
                nested_args[k] = v

        # Determine the type of args
        if isinstance(args, dict):
            for key, value in args.items():
                _add_pair(key, value)
        elif isinstance(args, (list, tuple)):
            for item in args:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    _add_pair(item[0], item[1])
                elif isinstance(item, str):
                    if "=" in item:
                        k, v = item.split("=", 1)
                        _add_pair(k.strip(), v.strip())
                # otherwise ignore non-conforming items
        else:
            # unsupported type – attempt to interpret as a single entry
            # possibly string or tuple
            if isinstance(args, str) and "=" in args:
                k, v = args.split("=", 1)
                _add_pair(k.strip(), v.strip())
            elif isinstance(args, (list, tuple)) and len(args) == 2:
                _add_pair(args[0], args[1])

        return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``.

    ``extra_vars`` may be:

    * ``None`` – nothing added.
    * A mapping – updated directly into ``vars_dict``.
    * An iterable of strings of the form ``'key=value'`` – parsed
      and added to ``vars_dict``.
    * Any other unsupported types are ignored.
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict

    result = vars_dict
    try:
        if isinstance(extra_vars, dict):
            result.update(extra_vars)
        else:
            # Accept lists, tuples, or any iterable
            for item in extra_vars:
                if isinstance(item, str):
                    if '=' in item:
                        key, value = item.split("=", 1)
                        key = key.strip()
                        value = value.strip()
                        if value:
                            # Try to interpret the value as a Python literal
                            # but fall back to string if parsing fails.
                            try:
                                # Using eval is unsafe; we mimic literal eval manually.
                                # Simple heuristic: numeric, bool, None, quoted strings.
                                if (value.startswith(("'", '"')) and
                                        value.endswith(("'", '"'))):
                                    value = value[1:-1]
                                elif value.lower() in ("true", "false"):
                                    value = value.lower() == "true"
                                else:
                                    num = float(value) if "." in value else int(value)
                                    value = num
                            except Exception:
                                # keep original string
                                pass
                        else:
                            value = None
                        result[key] = value
                elif isinstance(item, dict):
                    result.update(item)
                else:
                    # Unsupported item type; skip gracefully
                    continue
    finally:
        return result

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: The updated dictionary
    """
    # Validate inputs
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if not extra_vars:
        return vars_dict

    # Normalise extra_vars to a list of strings
    if isinstance(extra_vars, str):
        extra_items = [extra_vars]
    else:
        try:
            extra_items = list(extra_vars)
        except Exception as exc:
            raise TypeError("extra_vars must be iterable of strings") from exc

    for item in extra_items:
        if not isinstance(item, str):
            raise TypeError("Each extra-var must be a string")
        # Split on the first '='
        if '=' not in item:
            # Unable to parse, skip this entry
            continue
        key, _, value = item.partition('=')
        key = key.strip()
        value = value.strip()
        if not key:
            # Skip entries with empty keys
            continue
        # Attempt a simple type conversion: integer or float
        try:
            if '.' in value:
                conv_value = float(value)
            else:
                conv_value = int(value)
        except ValueError:
            # Keep as string if not a number
            conv_value = value
        # Merge into the vars_dict
        try:
            vars_dict[key] = conv_value
        except Exception as exc:
            # If we can't assign, raise an informative error
            raise RuntimeError(f"Failed to assign key '{key}' to vars_dict") from exc

    return vars_dict

