    if isinstance(verbose, int) and verbose > 0:
        cmd.extend(["-v"] * verbose)

    # Add any explicit ansible arguments
    if isinstance(ansible_args, dict):
        for key, value in ansible_args.items():
            # Determine flag string
            flag = key
            if not flag.startswith("-"):
                flag = f"--{flag}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
            elif isinstance(value, (list, tuple)):
                for val in value:
                    cmd.extend([flag, str(val)])
            else:
                # For None or False we skip
                if value is not None and value is not False:
                    cmd.extend([flag, str(value)])

    # Add extra-vars
    if isinstance(extra_vars, dict) and extra_vars:
        try:
            json_str = json.dumps(extra_vars)
        except Exception as exc:
            raise ValueError(f"Failed to serialize extra_vars: {exc}") from exc
        cmd.extend(["--extra-vars", json_str])

    # Execute command
    try:
        # Use stdout/stderr capture to avoid dropping output
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.path if hasattr(ir_workspace, "path") else None,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("The 'ansible-playbook' command was not found.") from exc
    except Exception as exc:
        raise RuntimeError(f"An error occurred while running ansible-playbook: {exc}") from exc

    # Log output if plugin provides a logging method
    log_method = getattr(ir_plugin, "LOG", None)
    if callable(log_method):
        if result.stdout:
            log_method("[Ansible stdout]\n" + result.stdout)
        if result.stderr:
            log_method("[Ansible stderr]\n" + result.stderr)

    if result.returncode != 0:
        raise RuntimeError(
            f"Ansible playbook exited with code {result.returncode}:\n"
            f"stdout: {result.stdout}\nstderr: {result.stderr}"
        )

    return result

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json

    # Build the base command
    cmd = ['ansible-playbook']

    # Add verbosity flags if provided
    if verbose is not None:
        try:
            v_lvl = int(verbose)
            if v_lvl > 0:
                cmd.append('-' + 'v' * v_lvl)
        except Exception:
            # Ignore if not a valid integer
            pass

    # Add inventory from the workspace if available
    inventory = None
    if hasattr(ir_workspace, "inventory_file"):
        inventory = ir_workspace.inventory_file
    elif hasattr(ir_workspace, "inventory_path"):
        inventory = ir_workspace.inventory_path
    elif hasattr(ir_workspace, "inventory"):
        inventory = ir_workspace.inventory

    if inventory:
        cmd.extend(['-i', inventory])

    # Append the playbook
    cmd.append(playbook_path)

    # Extra vars
    if extra_vars:
        try:
            # Convert dict to JSON string
            ev_json = json.dumps(extra_vars)
            cmd.extend(['--extra-vars', ev_json])
        except Exception as e:
            return {"stdout": "", "stderr": f"Failed to serialize extra_vars: {e}", "returncode": 1}

    # Additional ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            # Skip if the key is None
            if key is None:
                continue
            # Ensure key is string and prefix with '--' if not present
            opt = key if isinstance(key, str) and key.startswith('-') else f"--{key}"
            # Handle boolean flags
            if isinstance(value, bool):
                if value:
                    cmd.append(opt)
                continue
            # Otherwise treat as option with value
            cmd.extend([opt, str(value)])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
        return {
            "stdout": result.stdout,
            "stderr": result.stderr,
            "returncode": result.returncode,
        }
    except Exception as exc:
        return {"stdout": "", "stderr": str(exc), "returncode": 1}

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object representing the active
         workspace.
     :param ir_plugin: An InfraredPlugin object of the current plugin.
     :param playbook_path: the playbook to invoke.
     :param verbose: Ansible verbosity level (int or string like '-vv').
     :param extra_vars: dict. Passed to Ansible as --extra-vars.
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.

    Returns a ``subprocess.CompletedProcess`` instance.
    Raises a ``RuntimeError`` if the playbook execution fails.
    """
    try:
        # Base command
        cmd = ["ansible-playbook", playbook_path]

        # Add inventory if provided by the plugin
        inventory = None
        if getattr(ir_plugin, "inventory_path", None):
            inventory = ir_plugin.inventory_path
        if inventory:
            cmd.extend(["-i", inventory])

        # Verbosity
        if verbose is not None:
            if isinstance(verbose, int):
                if verbose > 0:
                    cmd.append("-" + "v" * verbose)
            elif isinstance(verbose, str):
                # Accept normal verbose flags like '-vv'
                if verbose.startswith("-"):
                    cmd.append(verbose)
                else:
                    cmd.append("-" + verbose)

        # Extra variables
        if extra_vars is not None:
            try:
                # Represent as JSON; this is the safest format for Ansible
                import json
                json_vars = json.dumps(extra_vars)
                cmd.extend(["--extra-vars", json_vars])
            except Exception as exc:
                raise ValueError(f"Could not serialize extra_vars: {exc}") from exc

        # Additional ansible-playbook arguments
        if ansible_args:
            for key, value in ansible_args.items():
                if isinstance(value, bool):
                    if value:               # only add flag if True
                        cmd.append(key)
                else:
                    cmd.extend([key, str(value)])

        # Determine working directory from the workspace, if available
        cwd = getattr(ir_workspace, "path", None) or None

        # Execute the command
        result = subprocess.run(
            cmd,
            cwd=cwd,
            capture_output=True,
            text=True,
        )

        if result.returncode != 0:
            # Build a meaningful error message
            error_msg = result.stderr.strip()
            raise RuntimeError(
                f"ansible-playbook failed with exit code {result.returncode}:\n{error_msg}"
            )

        return result

    except FileNotFoundError as fnf:
        raise RuntimeError("The 'ansible-playbook' command was not found. "
                           "Ensure Ansible is installed and in PATH.") from fnf
    except Exception as exc:
        raise RuntimeError(f"Error running ansible-playbook: {exc}") from exc

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
      workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
      directly to Ansible.
    :return: The stdout output of the ansible-playbook command
    :raises ValueError: If required arguments are missing or invalid
    :raises RuntimeError: If the ansible-playbook execution fails
    """
    # Local imports to avoid module level imports
    try:
        import json
        from subprocess import run, CalledProcessError
    except Exception as exc:
        raise RuntimeError("Failed to import required modules: %s" % exc) from exc

    # Basic argument validation
    if ir_workspace is None:
        raise ValueError("ir_workspace must not be None")
    if ir_plugin is None:
        raise ValueError("ir_plugin must not be None")
    if not playbook_path or not isinstance(playbook_path, str):
        raise ValueError("playbook_path must be a non-empty string")

    # Build the ansible-playbook command
    cmd = ["ansible-playbook"]

    # Verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose < 0:
                raise ValueError("verbose level must be non-negative")
            cmd.append("-" + "v" * verbose)
        elif isinstance(verbose, str):
            if verbose.startswith("-"):
                cmd.append(verbose)
            else:
                raise ValueError("verbose string must start with '-'")
        else:
            raise TypeError("verbose must be int or str")

    # Additional ansible arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if not key:
                continue
            k = key if key.startswith("--") else "--" + key.lstrip("-")
            if isinstance(value, bool):
                if value:
                    cmd.append(k)
            else:
                cmd.extend([k, str(value)])

    # Extra vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        try:
            extra_json = json.dumps(extra_vars, separators=(",", ":"))
        except Exception as exc:
            raise ValueError("Failed to serialize extra_vars to JSON: %s" % exc) from exc
        cmd.extend(["--extra-vars", extra_json])

    # Append the playbook path
    cmd.append(playbook_path)

    # Execute the command
    try:
        result = run(
            cmd,
            cwd=ir_workspace.path if hasattr(ir_workspace, "path") else None,
            check=True,
            capture_output=True,
            text=True
        )
        return result.stdout
    except CalledProcessError as exc:
        # Provide detailed error information
        err_msg = (
            f"ansible-playbook failed with return code {exc.returncode}\n"
            f"Command: {' '.join(cmd)}\n"
            f"Stdout: {exc.stdout}\n"
            f"Stderr: {exc.stderr}"
        )
        raise RuntimeError(err_msg) from exc
    except Exception as exc:
        raise RuntimeError(f"Error executing ansible-playbook: {exc}") from exc

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """
    Runs ansible cli with vars dict
    :param cli_args: List of ansible‑playbook command line arguments.
    :param vars_dict: dict, Will be passed as Ansible extra-vars.
    :param ir_workspace: An Infrared Workspace object representing the active workspace.
    :param ir_plugin: An InfraredPlugin object of the current plugin.
    :return: dict containing return code, stdout and stderr of the ansible execution.
    """
    # Basic input validation
    if not isinstance(cli_args, (list, tuple)):
        raise ValueError("cli_args must be a list or tuple of arguments")
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")
    # Build the command and working directory
    try:
        cmd = ["ansible-playbook"] + list(cli_args) + ["-e", json.dumps(vars_dict)]
    except Exception as exc:
        return {
            "returncode": -1,
            "stdout": "",
            "stderr": f"Error constructing command: {exc}",
            "error": str(exc),
        }

    cwd = getattr(ir_workspace, "path", None)

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            capture_output=True,
            text=True,
            check=True,
        )
        return {
            "returncode": result.returncode,
            "stdout": result.stdout,
            "stderr": result.stderr,
        }
    except subprocess.CalledProcessError as e:
        # Ansible returned non‑zero exit status
        return {
            "returncode": e.returncode,
            "stdout": e.stdout,
            "stderr": e.stderr,
            "error": str(e),
        }
    except Exception as e:
        # Any other runtime error
        return {
            "returncode": -1,
            "stdout": "",
            "stderr": f"Runtime error: {e}",
            "error": str(e),
        }

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    :return: The same dictionary with values cast to appropriate types
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")

    # Helper sets for simple type checks
    bool_true = {"true", "1", "yes", "on"}
    bool_false = {"false", "0", "no", "off"}

    for key, raw_val in list(values_dict.items()):
        try:
            if isinstance(raw_val, str):
                val = raw_val.strip()
                lowered = val.lower()

                # Boolean conversion
                if lowered in bool_true:
                    values_dict[key] = True
                    continue
                if lowered in bool_false:
                    values_dict[key] = False
                    continue

                # Integer conversion (handles decimal, hex, octal, binary)
                try:
                    if val.lower().startswith(("0x", "-0x", "0b", "-0b", "0o", "-0o")):
                        values_dict[key] = int(val, 0)
                    else:
                        values_dict[key] = int(val)
                    continue
                except ValueError:
                    pass

                # Float conversion
                try:
                    values_dict[key] = float(val)
                    continue
                except ValueError:
                    pass

                # List conversion: comma-separated values become a list
                if "," in val:
                    # Preserve surrounding spaces by stripping each item
                    values_dict[key] = [item.strip() for item in val.split(",")]
                    continue

                # If nothing matched, leave as string
            else:
                # Non-string types are left as is (or subclassed types are fine)
                continue
        except Exception as exc:
            # Log the exception if logger is available; otherwise ignore and keep original
            if hasattr(self, 'logger'):
                try:
                    self.logger.error(
                        f"Error converting key '{key}' with value '{raw_val}': {exc}"
                    )
                except Exception:
                    pass
            # Keep the original value untouched if conversion fails

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in place.
    The expected type for each argument is obtained from a mapping attribute
    on the instance, under the key ``parser_name``. The mapping can provide
    either a builtin type, a callable, or a string descriptor such as
    ``"int"``, ``"float"``, ``"bool"``, ``"list[int]"`` or ``"list[str]"``.
    If a value cannot be converted, a ``ValueError`` is raised.

    :param parser_name: The command name, e.g. 'main', 'virsh', 'ospd', etc.
    :param values_dict: Dictionary of argument names to string values.
    """
    # Retrieve the mapping; fall back to empty dict if none is defined.
    mapping_attr = getattr(self, "_arg_type_map", {})
    if not isinstance(mapping_attr, dict):
        mapping_attr = {}
    type_map = mapping_attr.get(parser_name, {})
    if not isinstance(type_map, dict):
        type_map = {}

    def _str_to_bool(v):
        """Convert a string (or non-str value) to a boolean."""
        if isinstance(v, bool):
            return v
        if isinstance(v, str):
            lowered = v.strip().lower()
            if lowered in ("true", "1", "yes", "y", "t"):
                return True
            if lowered in ("false", "0", "no", "n", "f"):
                return False
            raise ValueError(f"Invalid boolean value: {v!r}")
        return bool(v)

    for key, raw_value in list(values_dict.items()):
        # Skip keys that have no explicit cast defined.
        if key not in type_map:
            continue

        desired = type_map[key]
        try:
            if callable(desired):
                # If the desired is a callable, use it directly.
                casted = desired(raw_value)
            elif isinstance(desired, type):
                # Built-in type conversion (int, float, str, etc.).
                casted = desired(raw_value)
            elif isinstance(desired, str):
                if desired.lower() == "bool":
                    casted = _str_to_bool(raw_value)
                elif desired.lower() == "int":
                    casted = int(raw_value)
                elif desired.lower() == "float":
                    casted = float(raw_value)
                elif desired.lower().startswith("list["):
                    # Handle list[int], list[bool], list[float], list[str]
                    bracket = desired.find("[")
                    end_bracket = desired.rfind("]")
                    if bracket == -1 or end_bracket == -1 or end_bracket <= bracket:
                        raise ValueError(f"Unsupported list format: {desired!r}")
                    sub_type = desired[bracket+1:end_bracket].strip().lower()
                    parts = [p.strip() for p in str(raw_value).split(",") if p.strip() != ""]
                    if sub_type == "int":
                        casted = [int(p) for p in parts]
                    elif sub_type == "float":
                        casted = [float(p) for p in parts]
                    elif sub_type == "bool":
                        casted = [_str_to_bool(p) for p in parts]
                    elif sub_type == "str":
                        casted = parts
                    else:
                        raise ValueError(f"Unsupported list element type: {sub_type!r}")
                else:
                    # Fallback: keep as string if the descriptor is unknown.
                    casted = raw_value
            else:
                # Unknown descriptor; skip conversion.
                casted = raw_value
        except Exception as exc:
            raise ValueError(
                f"Failed to convert argument '{key}' with value {raw_value!r} "
                f"to type {desired!r}"
            ) from exc

        values_dict[key] = casted
    # The dictionary is modified in place; no explicit return needed.

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Basic validation
        if not isinstance(parser_name, str):
            raise TypeError("parser_name must be a string")
        if not isinstance(values_dict, dict):
            raise TypeError("values_dict must be a dictionary")

        # Helper to perform a safe cast
        def safe_cast(val, target_type):
            try:
                return target_type(val)
            except Exception:
                return val

        # Determine expected types if defined
        type_map = {}
        if hasattr(self, 'arg_type_mapping'):
            # Expecting dict of dict: {parser_name: {arg_name: type}}
            parser_map = self.arg_type_mapping
            if isinstance(parser_map, dict):
                type_map = parser_map.get(parser_name, {})

        # Helper to guess type when not explicitly provided
        def guess_and_cast(val):
            # None or already good type
            if val is None or not isinstance(val, str):
                return val

            stripped = val.strip()
            lower = stripped.lower()

            # Explicit boolean
            if lower in ("true", "false"):
                return lower == "true"

            # None-like
            if lower == "none":
                return None

            # Integer
            if stripped.lstrip("-+").isdigit():
                return int(stripped)

            # Float
            try:
                float_val = float(stripped)
                # Avoid casting "1e3" etc? We'll accept
                if "." in stripped or "e" in stripped.lower():
                    return float_val
            except Exception:
                pass

            # List separator detection (comma or space-separated)
            if "," in stripped:
                items = [item.strip() for item in stripped.split(",")]
                return [guess_and_cast(item) for item in items]
            if " " in stripped and len(stripped.split()) > 1:
                items = [item.strip() for item in stripped.split()]
                return [guess_and_cast(item) for item in items]

            # Default to string
            return val

        # Convert each value
        for key, value in list(values_dict.items()):
            target_type = type_map.get(key)
            if target_type:
                # Explicit type provided
                if isinstance(value, str):
                    new_val = safe_cast(value, target_type)
                else:
                    new_val = value
            else:
                # Use heuristic guess
                new_val = guess_and_cast(value)

            values_dict[key] = new_val

        # The dictionary is mutated in place; return None for clarity
        return None

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Cast arguments to correct types by modifying values_dict in place.
    By default all the values are strings.
    :param parser_name: The command name, e.g. main, virsh, ospd, etc.
    :param values_dict: The dict of arguments.
    """
    if not isinstance(values_dict, dict):
        return

    # Helper to convert a single value
    def _convert_value(val):
        if not isinstance(val, str):
            return val
        stripped = val.strip()
        if stripped == "":
            return val
        # Try integer
        try:
            return int(stripped)
        except ValueError:
            pass
        # Try float
        try:
            return float(stripped)
        except ValueError:
            pass
        # Try boolean
        lower = stripped.lower()
        if lower == "true":
            return True
        if lower == "false":
            return False
        # Try comma-separated list
        if "," in stripped:
            parts = [p.strip() for p in stripped.split(",")]
            return [_convert_value(p) for p in parts]
        return stripped

    # Perform conversion
    for key, val in list(values_dict.items()):
        try:
            values_dict[key] = _convert_value(val)
        except Exception:
            # Keep original if conversion fails
            values_dict[key] = val
    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Validate input types
        if not isinstance(parser_name, str):
            raise TypeError("parser_name must be a string")
        if not isinstance(values_dict, dict):
            raise TypeError("values_dict must be a dict")

        # Retrieve the argument type definitions for the given parser.
        # The implementation expects subclasses to provide a mapping
        # `self._arg_definitions` of the form:
        #   {parser_name: {arg_name: expected_type}}
        arg_defs = getattr(self, "_arg_definitions", {}).get(parser_name, {})

        for key, raw_val in list(values_dict.items()):
            expected_type = arg_defs.get(key)
            if expected_type is None:
                # No type information available; leave value as is
                continue

            try:
                # Handle boolean conversion explicitly
                if expected_type is bool:
                    if isinstance(raw_val, bool):
                        cast_val = raw_val
                    elif isinstance(raw_val, str):
                        lowered = raw_val.lower()
                        if lowered in ("true", "1", "yes", "y", "on"):
                            cast_val = True
                        elif lowered in ("false", "0", "no", "n", "off"):
                            cast_val = False
                        else:
                            raise ValueError(f"Invalid boolean string: {raw_val}")
                    else:
                        cast_val = bool(raw_val)

                # Handle list conversion (comma separated string to list of strings)
                elif expected_type is list:
                    if isinstance(raw_val, list):
                        cast_val = raw_val
                    elif isinstance(raw_val, str):
                        cast_val = [item.strip() for item in raw_val.split(",") if item.strip()]
                    else:
                        cast_val = [raw_val]

                # Handle any other built-in types (int, float, etc.)
                else:
                    cast_val = expected_type(raw_val)

                # Update the dictionary with the converted value
                values_dict[key] = cast_val

            except Exception:
                # Conversion failed; keep the original value to avoid data loss
                pass
        # No return value; the dictionary is modified in place.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        # try loading from JSON first
        spec_path = os.path.join(plugin_dir, "plugin.json")
        if not os.path.isfile(spec_path):
            # try YAML
            yaml_path = None
            for fn in ("plugin.yaml", "plugin.yml"):
                candidate = os.path.join(plugin_dir, fn)
                if os.path.isfile(candidate):
                    yaml_path = candidate
                    break
            if yaml_path is None:
                raise FileNotFoundError("No plugin spec file (plugin.json, plugin.yaml, or plugin.yml) found in '{}'".format(plugin_dir))
            # load YAML
            try:
                import yaml
                with open(yaml_path, "r", encoding="utf-8") as f:
                    data = yaml.safe_load(f)
            except ImportError as exc:
                raise RuntimeError("PyYAML is required to parse YAML spec files") from exc
            except yaml.YAMLError as exc:
                raise ValueError("Failed to parse YAML spec file '{}': {}".format(yaml_path, exc)) from exc
        else:
            with open(spec_path, "r", encoding="utf-8") as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError as exc:
                    raise ValueError("Failed to parse JSON spec file '{}': {}".format(spec_path, exc)) from exc

        if not isinstance(data, dict):
            raise ValueError("Plugin spec root must be a JSON/YAML object, got type '{}'".format(type(data).__name__))

        # recursive flatten
        def _flatten(d, parent_key=""):
            items = {}
            for k, v in d.items():
