def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    from pathlib import Path

    # Validate input
    if not isinstance(plugin_dir, (str, Path)):
        raise TypeError(f"plugin_dir must be a path-like object, got {type(plugin_dir).__name__}")
    plugin_path = Path(plugin_dir).expanduser().resolve()
    if not plugin_path.is_dir():
        raise FileNotFoundError(f"Plugin directory does not exist: {plugin_path}")

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='__'):
        items = {}
        for key, value in d.items():
            new_key = f"{parent_key}{sep}{key}" if parent_key else key
            if isinstance(value, dict):
                items.update(_flatten(value, new_key, sep=sep))
            else:
                items[new_key] = value
        return items

    # Candidate spec file names
    spec_candidates = [
        plugin_path / "plugin.json",
        plugin_path / "plugin.yaml",
        plugin_path / "plugin.yml",
        plugin_path / "spec.json",
        plugin_path / "spec.yaml",
        plugin_path / "spec.yml",
    ]

    spec_data = None
    for spec_file in spec_candidates:
        if spec_file.is_file():
            try:
                with spec_file.open('r', encoding='utf-8') as f:
                    if spec_file.suffix.lower() in {'.yaml', '.yml'}:
                        try:
                            import yaml
                        except Exception as exc:
                            raise ImportError(
                                f"YAML processing required but PyYAML is not installed: {exc}"
                            )
                        spec_data = yaml.safe_load(f)
                    else:  # assume JSON
                        spec_data = json.load(f)
                break  # stop after first found
            except Exception as exc:
                raise ValueError(f"Failed to read spec file '{spec_file}': {exc}") from exc

    if spec_data is None:
        # No spec file found, return empty dict
        return {}

    if not isinstance(spec_data, dict):
        raise ValueError(f"Spec file '{spec_file}' does not contain a JSON/YAML mapping object")

    return _flatten(spec_data)

