def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Basic type and value checks
    if path is None or root is None:
        raise ValueError("Both 'path' and 'root' must be non-None values.")
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("'path' and 'root' must be strings.")

    # Remove trailing path separators for uniform comparison
    # Handles both Unix "/" and Windows "\\" separators
    def _strip_trailing_sep(p):
        return p.rstrip("/\\")

    root_clean = _strip_trailing_sep(root)
    path_clean = _strip_trailing_sep(path)

    if root_clean == "":
        raise ValueError("The root path cannot be empty or just separators.")

    # If the path is exactly the root, return an empty string
    if path_clean == root_clean:
        return ""

    # Check if the path starts with the root followed by a separator
    for sep in ("/", "\\"):
        prefixed = root_clean + sep
        if path_clean.startswith(prefixed):
            # Return the part after the root
            return path_clean[len(prefixed):]

    # If we get here, the root isn't a prefix of the path
    raise ValueError(f"The specified root '{root}' is not a prefix of the path '{path}'.")
